/* TizenTube – tamna "TV" tema. Chromium 69: bez gap, inset, aspect-ratio. */
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1920px;height:1080px;overflow:hidden;background:#0b0b0f;color:#f2f2f5;font-family:"SamsungOneUI","Samsung Sans",Roboto,"Segoe UI",Arial,sans-serif}
.hidden{display:none!important}
button,input{font:inherit;color:inherit;background:none;border:0;outline:none}
button:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:2px solid #fff;outline-offset:2px}
svg{display:block;fill:currentColor}
:root{--acc:#ff2e4d;--acc2:#ff7a45;--card:#17171d;--line:rgba(255,255,255,.08);--dim:#9a9aa6}

/* ---------- bočni meni ---------- */
#rail{position:fixed;left:0;top:0;bottom:0;width:120px;z-index:5;padding-top:40px;
  background:linear-gradient(90deg,rgba(8,8,11,.98) 0,rgba(8,8,11,.92) 70%,rgba(8,8,11,0));transition:width .2s}
#rail.open{width:340px;background:linear-gradient(90deg,rgba(8,8,11,.99) 0,rgba(8,8,11,.96) 80%,rgba(8,8,11,0))}
.logo{height:60px;margin:0 0 50px 38px;display:flex;align-items:center}
.logo .lg{width:46px;height:46px;border-radius:13px;background:linear-gradient(135deg,var(--acc),var(--acc2));display:flex;align-items:center;justify-content:center;flex:none}
.logo .lg svg{width:26px;height:26px;fill:#fff}
.logo b{font-size:30px;margin-left:16px;opacity:0;transition:opacity .2s;white-space:nowrap;letter-spacing:.5px}
.navbtn{display:flex;align-items:center;height:76px;margin:6px 18px;padding:0 0 0 20px;border-radius:38px;color:#b7b7c2;width:84px;transition:width .2s,background .15s;white-space:nowrap;overflow:hidden}
.navbtn i{display:block;flex:none}
.navbtn svg{width:42px;height:42px;flex:none}
.navbtn span{font-size:28px;margin-left:24px;opacity:0;transition:opacity .2s}
#rail.open .navbtn{width:300px}
#rail.open .navbtn span,#rail.open .logo b{opacity:1}
.navbtn.sel{color:#fff}
.navbtn.sel svg{fill:var(--acc)}
.navbtn.focus{background:#fff;color:#111}
.navbtn.focus svg{fill:#111}

/* ---------- sadržaj ---------- */
#view{position:absolute;left:120px;top:0;right:0;bottom:0;overflow:hidden}
.page{position:absolute;left:0;right:0;top:0;padding:0 0 120px 40px;transition:transform .28s cubic-bezier(.2,.7,.2,1)}
.ptitle{font-size:46px;font-weight:700;margin:56px 0 30px 8px}
.shelf{margin-top:30px}
.shelf-title{font-size:30px;font-weight:600;margin:0 0 14px 8px;color:#e9e9ef;display:flex;align-items:center}
.shelf-title small{font-size:22px;color:var(--dim);font-weight:400;margin-left:16px}
.rowwrap{position:relative;overflow:hidden;padding:14px 0 18px 8px;margin:-14px 0 -18px -8px}
.row{display:flex;transition:transform .28s cubic-bezier(.2,.7,.2,1);padding-left:8px}
.row>*{margin-right:28px;flex:none}
.rarr{position:absolute;top:14px;width:70px;height:200px;display:none;align-items:center;justify-content:center;font-size:60px;z-index:2;background:rgba(0,0,0,.55);color:#fff;border-radius:14px}
.rarr.l{left:8px}.rarr.r{right:40px}
.rowwrap:hover .rarr{display:flex}
.grid{display:flex;flex-wrap:wrap;padding:14px 0 0 8px}
.grid>*{margin:0 28px 34px 0}

/* ---------- kartice ---------- */
.card{width:352px;position:relative;transition:transform .16s}
.card .th{position:relative;width:352px;height:198px;border-radius:16px;overflow:hidden;background:#1d1d24}
.card img{width:100%;height:100%;object-fit:cover;display:block}
.card .d{position:absolute;right:10px;bottom:10px;background:rgba(0,0,0,.82);padding:2px 9px;border-radius:7px;font-size:19px;font-weight:600}
.card .d.live{background:var(--acc)}
.card .pb{position:absolute;left:0;right:0;bottom:0;height:6px;background:rgba(255,255,255,.25)}
.card .pb i{display:block;height:100%;background:var(--acc)}
.card .t{font-size:23px;line-height:29px;max-height:58px;overflow:hidden;margin-top:12px;font-weight:500;color:#e6e6ec}
.card .m{font-size:19px;color:var(--dim);margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card.focus{transform:scale(1.06);z-index:2}
.card.focus .th{box-shadow:0 0 0 4px #fff,0 18px 40px rgba(0,0,0,.6)}
.card.focus .t{color:#fff}
.card.sk .th{background:linear-gradient(90deg,#18181e 0,#24242c 50%,#18181e 100%);background-size:700px 100%;animation:sk 1.3s infinite linear}
.card.sk .t{height:22px;width:80%;background:#1d1d24;border-radius:6px}
.card.sk .m{height:16px;width:50%;background:#1a1a20;border-radius:6px}
@keyframes sk{from{background-position:-350px 0}to{background-position:350px 0}}

/* kanali */
.chan{width:220px;text-align:center;padding:16px 0;border-radius:20px;transition:transform .16s}
.chan .av{width:150px;height:150px;border-radius:50%;margin:0 auto 14px;background:#2a2a33;display:flex;align-items:center;justify-content:center;font-size:62px;font-weight:700;overflow:hidden;color:#fff}
.chan .av img{width:100%;height:100%;object-fit:cover}
.chan .n{font-size:22px;padding:0 8px;max-height:56px;overflow:hidden}
.chan .c{font-size:18px;color:var(--dim);margin-top:4px}
.chan.focus{transform:scale(1.07);background:rgba(255,255,255,.08)}
.chan.focus .av{box-shadow:0 0 0 4px #fff}

/* čipovi */
.chip{padding:14px 30px;border-radius:30px;background:#1f1f27;font-size:24px;color:#d6d6de;transition:transform .12s;white-space:nowrap}
.chip.focus{background:#fff;color:#111;transform:scale(1.06)}
.chip.sel{background:rgba(255,46,77,.22);color:#fff;box-shadow:inset 0 0 0 2px var(--acc)}
.chip.sel.focus{background:#fff;color:#111}
.chips .sep{width:2px;height:40px;margin:6px 26px 16px 10px;background:var(--line)}
.chip.ic::before{content:"↻  ";color:var(--dim)}
.dym{font-size:24px;color:var(--dim);margin:0 0 14px 8px}
.dym b{color:#fff;font-style:italic}
.chip.ic.focus::before{color:#555}

/* ---------- hero ---------- */
#hero{position:relative;height:600px;margin:0 0 0 -40px;overflow:hidden}
#hero .bg{position:absolute;right:0;top:0;width:1300px;height:731px;object-fit:cover;opacity:.9}
#hero .fade{position:absolute;left:0;top:0;right:0;bottom:0;background:linear-gradient(90deg,#0b0b0f 0,#0b0b0f 28%,rgba(11,11,15,.75) 50%,rgba(11,11,15,0) 75%),linear-gradient(0deg,#0b0b0f 0,rgba(11,11,15,0) 40%)}
#hero .in{position:absolute;left:80px;top:110px;width:860px}
#hero .lbl{font-size:22px;letter-spacing:3px;text-transform:uppercase;color:var(--acc);font-weight:700}
#hero h1{font-size:54px;line-height:64px;margin:16px 0 18px;max-height:192px;overflow:hidden;font-weight:700}
#hero .meta{font-size:24px;color:#c4c4cc}
#hero .hpb{width:420px;height:6px;border-radius:3px;background:rgba(255,255,255,.2);margin-top:22px}
#hero .hpb i{display:block;height:100%;border-radius:3px;background:var(--acc)}
#hero .btns{display:flex;margin-top:34px}
#hero .btns>*{margin-right:20px}
.btn{display:flex;align-items:center;height:68px;padding:0 34px;border-radius:34px;font-size:26px;font-weight:600;background:rgba(255,255,255,.14);transition:transform .12s}
.btn svg{width:34px;height:34px;margin-right:10px}
.btn.pri{background:#fff;color:#111}
.btn.focus{transform:scale(1.07);box-shadow:0 0 0 4px rgba(255,255,255,.5)}
.btn.pri.focus{background:var(--acc);color:#fff;box-shadow:0 0 0 4px rgba(255,46,77,.35)}

/* ---------- pretraga ---------- */
.sbox{position:relative;display:flex;align-items:center;margin:56px 0 28px 8px;width:1500px}
.search-in{flex:1;height:84px;font-size:34px;padding:0 34px 0 84px;background:#1b1b22;border-radius:42px;border:3px solid transparent}
.search-in::placeholder{color:#9e9ea7;opacity:1}
.search-in.focus{border-color:#fff;background:#24242c}
.sbox svg.mag{position:absolute;left:28px;top:22px;width:40px;height:40px;fill:var(--dim);z-index:1}
.sbox .btn{margin-left:20px}
.chips{display:flex;flex-wrap:wrap;padding-left:8px}
.chips>*{margin:0 16px 16px 0}
.lbl2{font-size:22px;color:var(--dim);margin:6px 0 14px 8px;letter-spacing:1px;text-transform:uppercase}

/* postavke */
.setting{display:flex;align-items:center;justify-content:space-between;width:1200px;padding:22px 30px;margin:0 0 12px 8px;border-radius:18px;background:#15151b;font-size:27px}
.setting .lbl{color:#d6d6de}
.setting .val{padding:10px 26px;border-radius:24px;background:#25252e;font-size:25px;min-width:180px;text-align:center}
.setting.focus{background:#fff;color:#111}
.setting.focus .lbl{color:#111}
.setting.focus .val{background:var(--acc);color:#fff}
.setting input{width:640px;font-size:24px;padding:10px 18px;border-radius:12px;background:#25252e}
.setting.focus input{background:#eee;color:#111}
.keys{font-size:22px;color:var(--dim);margin:30px 0 0 8px;line-height:40px}
.dot{display:inline-block;width:18px;height:18px;border-radius:50%;margin:0 8px -2px 0}
.dot.r{background:#e53935}.dot.g{background:#43a047}.dot.y{background:#fdd835}.dot.b{background:#1e88e5}

#toast{position:fixed;left:50%;top:50px;transform:translate(-50%,-20px);background:rgba(30,30,38,.96);padding:16px 34px;border-radius:34px;font-size:25px;opacity:0;transition:opacity .2s,transform .2s;z-index:50;box-shadow:0 10px 30px rgba(0,0,0,.5);pointer-events:none}
#toast.show{opacity:1;transform:translate(-50%,0)}
.msg{font-size:26px;color:var(--dim);padding:20px 8px}

/* ---------- player ---------- */
#player{position:fixed;left:0;top:0;width:1920px;height:1080px;background:#000;z-index:10}
#video{position:absolute;left:0;top:0;width:100%;height:100%;background:#000}
#subs{position:absolute;left:0;right:0;bottom:110px;text-align:center;font-size:46px;line-height:58px;padding:0 160px;pointer-events:none;transition:bottom .2s}
#subs span{background:rgba(0,0,0,.7);padding:3px 16px;border-radius:8px;white-space:pre-line;-webkit-box-decoration-break:clone;box-decoration-break:clone;text-shadow:0 2px 4px #000}
#player.osd #subs{bottom:350px}
#osd{position:absolute;left:0;top:0;right:0;bottom:0;pointer-events:none;opacity:0;transition:opacity .25s}
#player.osd #osd{opacity:1}
#osd .top{position:absolute;left:0;right:0;top:0;height:240px;padding:50px 80px;background:linear-gradient(rgba(0,0,0,.8),transparent);display:flex;justify-content:space-between}
#osd-title{font-size:38px;font-weight:600;max-width:1500px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#osd-author{font-size:25px;color:#c8c8d0;margin-top:8px}
#osd-clock{font-size:34px;font-weight:300;color:#ddd}
#osd .bot{position:absolute;left:0;right:0;bottom:0;padding:120px 80px 50px;background:linear-gradient(transparent,rgba(0,0,0,.88))}
#osd-bar{height:8px;background:rgba(255,255,255,.22);border-radius:4px;position:relative}
#osd-bar{pointer-events:auto;cursor:pointer;transition:height .15s}
#osd-bar::before{content:"";position:absolute;left:0;right:0;top:-22px;bottom:-22px}
#player.scrub #osd-bar,#osd-bar:hover{height:12px}
#seekprev{position:absolute;bottom:34px;width:320px;text-align:center;pointer-events:none}
#seekprev .img{width:320px;height:180px;border-radius:12px;border:3px solid #fff;background-color:#111;background-repeat:no-repeat;box-shadow:0 10px 30px rgba(0,0,0,.7)}
#seekprev.noimg .img{display:none}
#seekprev .t{display:inline-block;margin-top:10px;padding:4px 14px;border-radius:8px;background:rgba(0,0,0,.75);font-size:28px;font-weight:600;font-variant-numeric:tabular-nums}
#osd-time .live{color:#fff;background:#e62117;border-radius:6px;padding:2px 10px;font-size:20px;font-weight:700;margin-right:10px}
#osd-time .behind{color:#a9a9b3;font-size:22px}
#osd-time .rem{color:#a9a9b3;margin-left:14px}
#osd-buf,#osd-pos{position:absolute;left:0;top:0;bottom:0;border-radius:4px}
#osd-buf{background:rgba(255,255,255,.35)}
#osd-pos{background:var(--acc)}
#osd-pos::after{content:"";position:absolute;right:-11px;top:-7px;width:22px;height:22px;border-radius:50%;background:#fff;box-shadow:0 0 8px rgba(0,0,0,.6)}
#osd-info{display:flex;justify-content:space-between;align-items:center;margin-top:18px}
#osd-time{font-size:26px;font-variant-numeric:tabular-nums}
#osd-status span{display:inline-block;margin-left:12px;padding:5px 14px;border-radius:8px;background:rgba(255,255,255,.14);font-size:20px;font-weight:600}
#pwrap{position:relative;margin-top:22px;pointer-events:auto}
#pctl{display:flex}
#pctl .pc{display:flex;align-items:center;margin-right:16px;padding:10px 22px 10px 16px;border-radius:14px;background:rgba(255,255,255,.1);border:2px solid transparent;transition:background .15s,transform .15s;cursor:pointer}
#pctl .pc svg{width:34px;height:34px;fill:#fff;margin-right:12px;opacity:.85}
#pctl .pc span{font-size:24px;font-weight:600;line-height:28px}
#pctl .pc small{display:block;font-size:16px;font-weight:400;color:#a9a9b3;line-height:20px}
#pctl .pc:hover{background:rgba(255,255,255,.2)}
#pctl .pc.focus{background:#fff;color:#111;transform:scale(1.05)}
#pctl .pc.focus svg{fill:#111}
#pctl .pc.focus small{color:#555}
#pctl .pc.open{border-color:var(--acc);background:rgba(255,255,255,.2)}
#pmenu{position:absolute;bottom:100%;margin-bottom:14px;min-width:320px;padding:10px;border-radius:18px;background:rgba(22,22,28,.96);box-shadow:0 20px 50px rgba(0,0,0,.6)}
#pmenu .mh{font-size:18px;color:#a9a9b3;text-transform:uppercase;letter-spacing:2px;padding:8px 18px 10px}
#pmenu .mi{font-size:26px;padding:12px 18px 12px 52px;border-radius:10px;position:relative;cursor:pointer;white-space:nowrap}
#pmenu .mi:hover{background:rgba(255,255,255,.12)}
#pmenu .mi.focus{background:#fff;color:#111}
#pmenu .mi.sel::before{content:"";position:absolute;left:20px;top:50%;width:14px;height:14px;margin-top:-7px;border-radius:50%;background:var(--acc)}
#osd-help{font-size:20px;color:#a9a9b3;margin-top:16px}
#osd-help b{font-weight:400;margin-right:28px}
#bigplay{position:absolute;left:50%;top:50%;width:150px;height:150px;margin:-75px 0 0 -75px;border-radius:50%;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity .2s}
#bigplay svg{width:80px;height:80px;fill:#fff}
#player.paused #bigplay{opacity:1}
#spinner{position:absolute;left:50%;top:50%;width:90px;height:90px;margin:-45px 0 0 -45px;border-radius:50%;border:7px solid rgba(255,255,255,.15);border-top-color:var(--acc);animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
#upnext{position:absolute;right:70px;bottom:250px;width:520px;background:rgba(20,20,26,.94);border-radius:20px;overflow:hidden;box-shadow:0 20px 50px rgba(0,0,0,.6);transition:transform .3s,opacity .3s}
#upnext img{width:100%;height:292px;object-fit:cover;display:block}
#upnext .x{padding:18px 24px 22px}
#upnext .l{font-size:20px;color:var(--acc);font-weight:700;letter-spacing:2px;text-transform:uppercase}
#upnext .tt{font-size:26px;margin-top:8px;max-height:68px;overflow:hidden}
#upnext .h{font-size:19px;color:var(--dim);margin-top:10px}
#upnext .cd{position:absolute;left:0;top:286px;height:6px;background:var(--acc);width:0}

/* Android telefon (dodir) */
.touch,.touch body{-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}
.touch #player{height:100%}


/* SponsorBlock oznake na traci (TV) */
#osd-bar .sbm{position:absolute;top:0;bottom:0;background:#00d400;opacity:.85;pointer-events:none}
#osd-bar .sbm.selfpromo{background:#ffff00}
#osd-bar .sbm.interaction{background:#cc00ff}

/* profil kanala */
.chead{display:flex;align-items:center;margin:48px 8px 30px}
.chead .cav{margin-right:36px} /* fallback: flex gap nije podržan na Tizen 5.5 (Chromium 69) */
.cav{flex:none;width:140px;height:140px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:60px;font-weight:700;color:#fff}
.cav img{width:100%;height:100%;object-fit:cover;display:block}
.cinfo{min-width:0}
.cname{font-size:46px;font-weight:700;line-height:1.15}
.cmeta{font-size:22px;color:var(--dim);margin-top:8px}
.cdesc{font-size:22px;line-height:1.35;color:var(--dim);margin-top:10px;max-width:1100px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;white-space:pre-line}
.cdesc.open{-webkit-line-clamp:unset;display:block}

files.css/phone.css:
/* Telefon (Android): isti interfejs, prilagođen dodiru i malom ekranu. Sve pod .phone, TV ne dira.
   Uspravno: donja traka s tabovima, kartice preko cijele širine, player gore + kontrole ispod.
   Položeno: uska lijeva traka, 3 kolone, player preko cijelog ekrana. */
.phone,.phone body{width:100%;height:100%;font-size:14px;touch-action:manipulation;
  -webkit-text-size-adjust:100%;text-size-adjust:100%}
.phone{--sat:0px;--sal:0px;--sar:0px;--sab:0px} /* izrez kamere (notch), puni ih mobile.js iz Jave */
.phone #app{position:fixed;left:0;top:0;right:0;bottom:0}
.phone input,.phone textarea{-webkit-user-select:text;user-select:text} /* u polju se ipak može birati/kursor */

/* bez TV fokusa */
.phone .focus{transform:none!important;box-shadow:none!important}
.phone .card.focus .th{box-shadow:none}
.phone .navbtn.focus{background:none;color:#b7b7c2}
.phone .navbtn.focus svg{fill:currentColor}
.phone .navbtn.sel.focus{color:#fff}
.phone .navbtn.sel.focus svg{fill:var(--acc)}
.phone .chip.focus{background:#1f1f27;color:#d6d6de}
.phone .chip.sel.focus{background:rgba(255,46,77,.22);color:#fff}
.phone .setting.focus{background:#15151b;color:inherit}
.phone .setting.focus .lbl{color:#d6d6de}
.phone .setting.focus .val{background:#25252e}
.phone .btn.pri.focus{background:#fff;color:#111}
.phone #pctl .pc.focus{background:rgba(255,255,255,.1);color:#fff}
.phone #pctl .pc.focus svg{fill:#fff}
.phone #pmenu .mi.focus{background:none;color:inherit}
.phone .chan.focus{background:none}
.phone .chan.focus .av{box-shadow:none}
.phone .search-in.focus{border-color:transparent;background:#1b1b22} /* .focus je TV fokus, ne stvarni kursor */
.phone .search-in:focus{border-color:rgba(255,255,255,.85);background:#24242c}

/* ---------- navigacija ---------- */
.phone #rail,.phone #rail.open{position:fixed;left:0;right:0;top:auto;bottom:0;width:auto;height:calc(56px + var(--sab));padding:0 0 var(--sab);display:flex;
  background:rgba(11,11,15,.97);border-top:1px solid var(--line);transition:none}
.phone .logo{display:none}
.phone .navbtn,.phone #rail.open .navbtn{flex:1;width:auto;height:56px;margin:0;padding:0;border-radius:0;flex-direction:column;justify-content:center}
.phone .navbtn svg{width:24px;height:24px}
.phone .navbtn span,.phone #rail.open .navbtn span{font-size:10px;margin:2px 0 0;opacity:1}
.phone #view{left:0;bottom:calc(56px + var(--sab));overflow-x:hidden;overflow-y:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.phone #view::-webkit-scrollbar{display:none}
.phone .page,.phone .row{transform:none!important;transition:none}
.phone .page{position:relative;padding:0 0 24px 12px}
.phone .ptitle{font-size:24px;line-height:30px;margin:22px 12px 14px 0}
.phone .msg{font-size:15px;line-height:22px;padding:16px 12px 16px 0}

/* ---------- redovi i mreže ---------- */
.phone .shelf{margin-top:18px}
.phone .shelf-title{font-size:17px;margin:0 0 8px 0}
.phone .shelf-title small{font-size:12px;margin-left:8px}
.phone .rowwrap{overflow-x:auto;overflow-y:hidden;padding:0;margin:0;scrollbar-width:none}
.phone .rowwrap::-webkit-scrollbar{display:none}
.phone .rarr{display:none!important}
.phone .row{padding:0 12px 0 0}
.phone .row>*{margin-right:10px}
.phone .grid{padding:6px 12px 0 0}
.phone .grid>*{margin:0 0 18px}

/* kartice: sličica 16:9 bez aspect-ratio */
.phone .card{width:64vw}
.phone .row>.card{max-width:320px} /* na tabletu red ne rasteže karticu preko pola ekrana */
.phone .grid .card{width:100%}
.phone .card .th{width:100%;height:0;padding-top:56.25%;border-radius:12px}
.phone .card .th img{position:absolute;left:0;top:0}
.phone .card .d{right:6px;bottom:6px;font-size:11px;padding:1px 5px;border-radius:4px}
.phone .card .pb{height:3px}
.phone .card .t{font-size:14px;line-height:19px;max-height:38px;margin-top:7px;overflow:hidden;
  overflow-wrap:anywhere;word-break:break-word;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical} /* "…" umjesto odsječenog reda */
.phone .card .m{font-size:12px;margin-top:2px}
.phone .card.sk .t{height:14px;display:block}
.phone .card.sk .m{height:11px}
.phone .grid .card .t,.phone .grid .card .m{padding-right:4px}

.phone .chan{width:90px;padding:6px 0;border-radius:12px}
.phone .chan .av{width:64px;height:64px;font-size:26px;margin-bottom:6px}
.phone .chan .n{font-size:12px;max-height:32px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.phone .chan .c{font-size:10px;max-height:26px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.phone .grid .chan{width:33.3%;margin:0 0 12px}

/* čipovi, dugmad */
.phone .chips{padding:0;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;margin-right:0;padding-right:12px;
  overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}
.phone .chips::-webkit-scrollbar{display:none}
.phone .chips>*{margin:0 8px 10px 0;flex:none}
.phone .chips .sep{height:24px;margin:10px 10px 0 2px;flex:none}
.phone .chip{display:inline-flex;align-items:center;height:44px;padding:0 16px;border-radius:22px;font-size:13px}
.phone .dym{font-size:13px;margin:0 0 8px}
.phone .lbl2{font-size:11px;margin:4px 0 8px}
.phone .btn{height:auto;min-height:44px;padding:9px 18px;border-radius:22px;font-size:14px;line-height:20px;text-align:center}
.phone .btn svg{width:20px;height:20px;margin-right:6px;flex:none}

/* hero */
.phone #hero{height:auto;margin:0 0 0 -12px}
.phone #hero .bg{position:relative;display:block;width:100%;height:56.25vw;opacity:1}
.phone #hero .fade{bottom:auto;height:56.25vw;background:linear-gradient(0deg,#0b0b0f 0,rgba(11,11,15,.92) 12%,rgba(11,11,15,.5) 30%,rgba(11,11,15,0) 62%)}
.phone #hero .in{position:relative;left:0;top:0;width:auto;margin-top:-34px;padding:0 12px}
.phone #hero .lbl{font-size:11px;letter-spacing:2px;text-shadow:0 1px 3px rgba(0,0,0,.7)}
.phone #hero h1{font-size:19px;line-height:24px;margin:6px 0 6px;max-height:72px;text-shadow:0 2px 8px rgba(0,0,0,.65)}
.phone #hero .meta{font-size:12px;text-shadow:0 1px 4px rgba(0,0,0,.65)}
.phone #hero .hpb{width:60%;height:3px;margin-top:10px}
.phone #hero .btns{margin-top:14px}
.phone #hero .btns>*{margin-right:10px}

/* pretraga */
.phone .sbox{width:auto;margin:12px 12px 14px 0}
.phone .search-in{height:44px;font-size:16px;padding:0 14px 0 42px;border-radius:22px;border-width:2px;min-width:0}
.phone .sbox svg.mag{left:13px;top:11px;width:22px;height:22px}
.phone .sbox .btn{margin-left:8px}

/* postavke */
.phone .setting{width:auto;min-height:52px;margin:0 12px 8px 0;padding:12px 14px;border-radius:12px;font-size:14px;flex-wrap:wrap}
.phone .setting .lbl{flex:1;margin-right:10px}
.phone .setting .val{padding:6px 12px;font-size:13px;min-width:0;border-radius:14px;white-space:nowrap}
.phone .setting input{flex:1 1 100%;width:100%;min-width:0;height:40px;margin:8px 0 0;font-size:15px;padding:0 12px;border-radius:10px;text-overflow:ellipsis}
.phone .setting .val.sw{position:relative;flex:none;width:50px;height:30px;padding:0;border-radius:15px;font-size:0;background:#3a3a45;transition:background-color .2s}
.phone .setting .val.sw::after{content:"";position:absolute;left:3px;top:3px;width:24px;height:24px;border-radius:50%;background:#c9c9d2;
  box-shadow:0 1px 3px rgba(0,0,0,.4);transition:transform .2s cubic-bezier(.2,.8,.2,1),background-color .2s}
.phone .setting .val.sw.on{background:var(--acc)}
.phone .setting .val.sw.on::after{transform:translateX(20px);background:#fff}
.phone .keys{display:none}
.phone input{scroll-margin:90px 0} /* tastatura ne prekrije polje kad ga fokusira */

.phone #toast{top:auto;bottom:calc(72px + var(--sab));font-size:14px;padding:9px 18px;border-radius:20px;max-width:90vw;transform:translate(-50%,10px)}
.phone #toast.show{transform:translate(-50%,0)}
.phone #toast{pointer-events:none;text-align:center}
.phone #player:not(.hidden):not(.mini)~#toast{top:calc(var(--sat) + 12px);bottom:auto;transform:translate(-50%,-10px)}
.phone #player:not(.hidden):not(.mini)~#toast.show{transform:translate(-50%,0)}
.phone .chip.ic::before{content:"↻";margin-right:6px} /* u flex čipu razmak iz content-a nestane */

/* ---------- player ---------- */
.phone #player{width:100%;height:100%}
.phone #subs{font-size:16px;line-height:21px;padding:0 16px;bottom:16px}
.phone #player.osd #subs{bottom:120px}
.phone #osd .top{height:auto;padding:14px 16px 40px}
.phone #osd-title{font-size:16px;max-width:100%}
.phone #osd .top>div:first-child{flex:1;min-width:0;padding-right:12px}
.phone #osd-author{font-size:12px;margin-top:2px}
.phone #osd-clock,.phone #osd-help{display:none}
.phone #osd .bot{padding:40px 16px calc(10px + var(--sab))}
.phone #osd-bar{height:4px}
.phone #osd-bar::before{top:-20px;bottom:-20px} /* 44px meta za prst */
.phone #player.scrub #osd-bar{height:6px}
.phone #osd-pos::after{right:-7px;top:-5px;width:14px;height:14px}
.phone #seekprev{width:160px;position:fixed;bottom:auto;z-index:30}
.phone #seekprev .img{width:160px;height:90px;border-width:2px;border-radius:8px}
.phone #seekprev .t{font-size:13px;padding:2px 8px}
.phone #osd-info{margin-top:10px}
.phone #osd-time{font-size:13px}
.phone #osd-time .live{font-size:11px;padding:1px 6px}
.phone #osd-time .behind{font-size:11px}
.phone #osd-status span{font-size:10px;padding:2px 7px;margin-left:5px}
.phone #pwrap{margin-top:10px}
.phone #pctl{flex-wrap:wrap}
.phone #pctl .pc{min-height:44px;margin:0 6px 6px 0;padding:6px 10px 6px 8px;border-radius:10px;border-width:1px}
.phone #pctl .pc svg{width:20px;height:20px;margin-right:6px}
.phone #pctl .pc span{font-size:12px;line-height:15px}
.phone #pctl .pc small{font-size:10px;line-height:12px}
/* meni playera: donja ploča */
.phone #pmenu{position:fixed;left:0!important;right:0;bottom:0;top:auto;margin:0;min-width:0;max-height:55vh;overflow-y:auto;
  border-radius:16px 16px 0 0;padding:8px 8px calc(16px + var(--sab));z-index:20;overscroll-behavior:contain}
.phone #pmenu .mh{font-size:11px;padding:6px 12px 8px}
.phone #pmenu .mi{min-height:44px;font-size:15px;padding:12px 12px 12px 40px}
.phone #pmenu .mi.sel::before{left:16px;width:10px;height:10px;margin-top:-5px}
.phone #bigplay{width:64px;height:64px;margin:-32px 0 0 -32px}
/* nevidljivo centralno dugme ne smije hvatati dodir (blokira 2x long-press i pinch) */
.phone #player:not(.paused):not(.osd) #bigplay{pointer-events:none;visibility:hidden}
.phone #bigplay svg{width:34px;height:34px}
.phone #spinner{width:44px;height:44px;margin:-22px 0 0 -22px;border-width:4px}
.phone #upnext{right:12px;bottom:auto;top:12px;width:200px;border-radius:12px}
.phone #upnext img{height:112px}
.phone #upnext .cd{top:109px;height:3px}
.phone #upnext .x{padding:8px 10px 10px}
.phone #upnext .l{font-size:10px;letter-spacing:1px}
.phone #upnext .tt{font-size:12px;max-height:32px;margin-top:3px}
.phone #upnext .h{display:none}
/* lista "Sljedeće" (samo uspravno, ispod naslova) */
#prel{display:none}
.phone #prel .rh{font-size:15px;font-weight:600;padding:4px 16px 10px}
.phone #prel .ri{display:flex;padding:6px 16px;cursor:pointer}
.phone #prel .ri:active{background:rgba(255,255,255,.08)}
.phone #prel .th{position:relative;flex:none;width:168px;height:94px;border-radius:8px;overflow:hidden;background:#1b1b22;transition:transform .15s ease-out}
.phone #prel .ri:active .th{transform:scale(.96)}
.phone #prel img{width:100%;height:100%;object-fit:cover;display:block}
.phone #prel .d{position:absolute;right:5px;bottom:5px;font-size:11px;font-weight:600;padding:1px 5px;border-radius:4px;background:rgba(0,0,0,.8)}
.phone #prel .d.live{background:#c00}
.phone #prel .tx{flex:1;min-width:0;padding-left:12px}
.phone #prel .t{font-size:14px;line-height:19px;font-weight:500;max-height:57px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical}
.phone #prel .m{font-size:12px;line-height:16px;color:var(--dim);margin-top:4px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}

/* ---------- pokreti: povlačenje, snap, ulaz ---------- */
.phone #player.drag,.phone #player.drag #video{transition:none!important}
.phone #player.drag #osd{pointer-events:none}
.phone #player.snap{transition:transform .28s cubic-bezier(.2,.8,.2,1),opacity .28s,background-color .28s}
.phone #player.snap #video{transition:transform .28s cubic-bezier(.2,.8,.2,1)!important}
.phone #player.snap #osd{transition:opacity .28s}
.phone #player.enter{animation:plin .3s cubic-bezier(.2,.8,.2,1)}
@keyframes plin{from{transform:translateY(40%);opacity:0}}
#seekfx{display:none}
.phone #seekfx{display:flex;position:absolute;width:40%;align-items:center;justify-content:center;font-size:15px;font-weight:600;
  pointer-events:none;opacity:0;z-index:2}
.phone #seekfx.c{opacity:1;left:50%;width:auto;height:30px!important;top:12px!important;transform:translateX(-50%);padding:0 14px;border-radius:15px;background:rgba(0,0,0,.65)}
.phone #seekfx.l{left:0;border-radius:0 50% 50% 0;background:radial-gradient(circle at 30% 50%,rgba(255,255,255,.22),rgba(255,255,255,.06) 70%);animation:sfx .9s}
.phone #seekfx.r{right:0;border-radius:50% 0 0 50%;background:radial-gradient(circle at 70% 50%,rgba(255,255,255,.22),rgba(255,255,255,.06) 70%);animation:sfx .9s}
@keyframes sfx{0%{opacity:0}15%{opacity:1}70%{opacity:1}100%{opacity:0}}

/* ---------- mini player: traka iznad tabova, aplikacija ostaje upotrebljiva ---------- */
#mini{display:none}
.phone #player.mini{top:auto;bottom:calc(56px + var(--sab));height:64px;background:#1b1b22;overflow:visible;box-shadow:0 -8px 24px rgba(0,0,0,.5);
  border-top:1px solid var(--line);touch-action:none}
.phone #player.mini #video{left:0;top:0;width:114px;height:64px}
.phone #player.mini #osd,.phone #player.mini #subs,.phone #player.mini #bigplay,.phone #player.mini #spinner,
.phone #player.mini #upnext,.phone #player.mini #seekfx{display:none!important}
.phone #player.mini #mini{display:flex;align-items:center;position:absolute;left:114px;right:0;top:0;height:64px;padding-left:12px}
.phone #mini .tx{flex:1;min-width:0}
.phone #mini b{display:block;font-size:13px;line-height:17px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.phone #mini span{display:block;font-size:12px;color:var(--dim);margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.phone #mini button{flex:none;width:48px;height:64px;display:flex;align-items:center;justify-content:center;border-radius:50%}
.phone #mini button:active{background:rgba(255,255,255,.1)}
.phone #mini button svg{width:26px;height:26px;fill:#fff}
.phone #mini .mp{position:absolute;left:-114px;right:0;bottom:0;height:2px;background:rgba(255,255,255,.15)}
.phone #mini .mp i{display:block;height:100%;width:0;background:var(--acc)}
.phone.hasmini #view{bottom:calc(120px + var(--sab))}
.phone.hasmini #toast{bottom:calc(136px + var(--sab))}

/* ---------- dodir: odziv, snap redova, glatki prelazi ---------- */
.phone *{-webkit-tap-highlight-color:transparent}
.phone #view{overscroll-behavior:contain}
.phone .rowwrap{scroll-snap-type:x mandatory;overscroll-behavior-x:contain;-webkit-overflow-scrolling:touch}
.phone .row>*{scroll-snap-align:start}
.phone .chips{scroll-snap-type:x proximity}
.phone .chips>*{scroll-snap-align:start}
.phone .card .th,.phone .chan,.phone .chip,.phone .btn,.phone .setting,.phone .navbtn svg{transition:transform .15s ease-out,opacity .15s,background-color .15s}
.phone .card:active .th,.phone .chan:active{transform:scale(.96)}
.phone .chip:active,.phone .btn:active{transform:scale(.95)!important}
.phone .setting:active{background:#202028;transform:none!important}
.phone .navbtn:active svg{transform:scale(.85)}
.phone #pctl .pc:active{background:rgba(255,255,255,.22)}
.phone #pmenu .mi:active{background:rgba(255,255,255,.12)}
.phone .page{animation:pgin .22s ease-out}
@keyframes pgin{from{opacity:0}}

/* telefon nema pravi hover: spriječi da :hover ostane zaglavljen nakon dodira */
@media (hover:none){
  .phone #pctl .pc:hover{background:rgba(255,255,255,.1)}
  .phone #pmenu .mi:hover{background:none}
  .phone #osd-bar:hover{height:4px}
  .phone .rowwrap:hover .rarr{display:none}
}

/* uspravno: video gore 16:9, kontrole stalno vidljive ispod njega */
@media (orientation:portrait){
  .phone #view{top:var(--sat)}
  .phone #player{border-top:var(--sat) solid #000} /* video ispod kamere, ne preko nje */
  .phone #video{height:56.25vw}
  .phone #osd{top:56.25vw;opacity:1!important;display:flex;flex-direction:column;overflow-y:auto;pointer-events:auto}
  .phone #osd .bot{position:relative;order:2;background:none;padding:14px 16px calc(6px + var(--sab))}
  .phone #osd .top{position:relative;order:1;background:none;padding:10px 16px 20px;display:block}
  .phone #osd-title{white-space:normal;font-size:17px;line-height:22px}
  .phone #osd-author{font-size:13px;margin-top:6px}
  .phone #subs,.phone #player.osd #subs{bottom:auto;top:calc(56.25vw - 12px);transform:translateY(-100%)}
  .phone #bigplay,.phone #spinner{top:28.125vw}
  /* "Sljedeće" ostaje unutar videa: nikad preko komentara i kontrola (PL-05/WEB-01) */
  .phone #upnext{top:12px;max-height:calc(56.25vw - 24px);overflow:hidden}
  .phone #pcm{order:3}
  .phone #prel{display:block;order:4;padding-bottom:16px}
  .phone #osd .top{border-bottom:1px solid var(--line);margin-bottom:12px}
}

/* položeno: uska traka lijevo, 3 kolone */
@media (orientation:landscape){
  .phone #rail,.phone #rail.open{right:auto;top:0;width:calc(64px + var(--sal));padding-left:var(--sal);padding-bottom:var(--sab);height:auto;flex-direction:column;justify-content:center;border-top:0;border-right:1px solid var(--line)}
  .phone .navbtn,.phone #rail.open .navbtn{flex:none;height:60px}
  .phone #view{left:calc(64px + var(--sal));right:var(--sar);bottom:0}
  .phone .ptitle{margin-top:16px}
  .phone #toast{bottom:calc(20px + var(--sab))}
  .phone #player.mini{left:calc(64px + var(--sal));bottom:var(--sab);width:auto;right:var(--sar)}
  .phone #osd .top,.phone #osd .bot{padding-left:calc(16px + var(--sal));padding-right:calc(16px + var(--sar))}
  .phone #osd .bot{padding-bottom:calc(10px + var(--sab))}
  /* komentari: ispod naslova, iznad kontrola, i primaju dodir (#osd je pointer-events:none) */
  .phone #pcm{position:absolute;left:calc(16px + var(--sal));top:112px;width:360px;max-width:55%;margin:0;z-index:2;pointer-events:none}
  .phone #player.osd #pcm{pointer-events:auto}
  .phone.hasmini #view{bottom:calc(64px + var(--sab))}
  .phone.hasmini #toast{bottom:calc(80px + var(--sab))}
  .phone .card{width:30vw}
  .phone .row>.card{max-width:300px}
  .phone .grid .card{width:33.33%;padding-right:10px}
  .phone .grid .chan{width:16.6%}
  .phone #hero .bg{height:58vh;object-position:center 25%}
  .phone #hero .fade{height:58vh}
  .phone #hero .in{margin-top:-10px;width:74%}
  /* kontrole u jednom redu (horizontalno skrolaju) da titlovi imaju stalno mjesto iznad njih */
  .phone #pctl{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}
  .phone #pctl::-webkit-scrollbar{display:none}
  .phone #pctl .pc{flex:none}
  .phone #player.osd #subs{bottom:150px}
  .phone #player:not(.hidden):not(.mini)~#toast{top:84px} /* ispod naslova, ne preko njega */
}
/* kratki landscape (640x320): svih 6 stavki mora stati u visinu */
@media (orientation:landscape) and (max-height:380px){
  .phone .navbtn,.phone #rail.open .navbtn{height:48px}
  .phone .navbtn span,.phone #rail.open .navbtn span{font-size:9px;margin-top:1px}
}

/* veći telefoni / tablet: krupniji tekst i dvije kolone, da se 800px ne rastegne kao telefon */
@media (min-width:600px){
  .phone .ptitle{font-size:26px;line-height:32px}
  .phone .shelf-title{font-size:18px}
  .phone #hero h1{font-size:22px;line-height:28px;max-height:84px}
  .phone #hero .meta{font-size:13px}
  .phone .card .t{font-size:15px;line-height:20px;max-height:40px}
  .phone .chip{font-size:14px}
  .phone .navbtn span{font-size:11px}
}
@media (min-width:600px) and (orientation:portrait){
  .phone #hero .bg{height:300px}
  .phone #hero .fade{height:300px}
  .phone #hero .in{margin-top:-38px}
  .phone .grid{justify-content:space-between}
  .phone .grid .card{width:calc(50% - 6px)}
  .phone .grid .chan{width:25%}
}

/* ---------- kartica: avatar | naslov + meta | ⋮ ---------- */
.phone .card .cr{display:flex;align-items:flex-start;margin-top:9px}
.phone .card .cr .tx{flex:1;min-width:0}
.phone .card .cr .t{margin-top:0;font-weight:600;color:#f1f1f1}
.phone .card .cr .m{color:#9e9ea7;margin-top:3px}
.phone .cav{flex:none;width:36px;height:36px;margin-right:10px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;
  font-size:15px;font-weight:700;color:#fff}
.phone .cav img,.phone .chan .av img{width:100%;height:100%;object-fit:cover;display:block}
.phone .card .more{flex:none;width:44px;min-width:44px;height:44px;margin:-8px -8px 0 0;padding:0;border:0;background:none;display:flex;align-items:center;justify-content:center;border-radius:50%}
.phone .card .more svg{width:20px;height:20px;fill:#c8c8d0}
.phone .card .more:active{background:rgba(255,255,255,.1)}
.phone .row .card .cav{display:none} /* u uskom redu nema mjesta za avatar */
.phone .card.gone{opacity:0;transform:scale(.96);transition:opacity .2s,transform .2s}
.phone .card.sk .t,.phone .card.sk .m{background:linear-gradient(90deg,#18181e 0,#24242c 50%,#18181e 100%);background-size:700px 100%;animation:sk 1.3s infinite linear}

/* historija / gledaj kasnije: kompaktni redovi (sličica lijevo) */
.phone .grid.hl .card{display:flex;width:100%;margin-bottom:12px}
.phone .grid.hl .card .th{flex:none;width:40%;padding-top:22.5%} /* 16:9 od 40% širine kartice */
.phone .grid.hl .card .cr{flex:1;min-width:0;margin:0 0 0 12px}
.phone .grid.hl .card .cav{display:none}
.phone .grid.hl .card .t{font-size:14px}
.phone .chips.tabs{margin-bottom:6px}
.phone .chip.warn{background:rgba(255,46,77,.25);color:#fff}

/* donji meni (dugi pritisak / ⋮) */
#sheet{position:fixed;left:0;top:0;right:0;bottom:0;z-index:300;background:rgba(0,0,0,0);transition:background-color .2s}
#sheet.on{background:rgba(0,0,0,.55)}
#sheet .sh{position:absolute;left:0;right:0;bottom:0;max-width:560px;margin:0 auto;padding:6px 0 calc(10px + var(--sab));background:#1c1c22;
  border-radius:16px 16px 0 0;transform:translateY(100%);transition:transform .22s ease-out;max-height:80vh;overflow-y:auto}
#sheet.on .sh{transform:none}
#sheet .grab{width:36px;height:4px;border-radius:2px;background:#4a4a55;margin:4px auto 8px}
#sheet .shh{display:flex;align-items:center;padding:4px 16px 12px;border-bottom:1px solid var(--line);margin-bottom:6px}
#sheet .shh img{width:96px;height:54px;border-radius:8px;object-fit:cover;flex:none;margin-right:12px;background:#111}
#sheet .shh .tx{min-width:0}
#sheet .shh .t{font-size:14px;font-weight:600;line-height:18px;max-height:36px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
#sheet .shh .m{font-size:12px;color:#9e9ea7;margin-top:3px}
#sheet .si{display:flex;align-items:center;height:50px;padding:0 20px;font-size:15px;color:#ececf1}
#sheet .si svg{width:22px;height:22px;fill:#d6d6de;margin-right:18px;flex:none}
#sheet .si:active{background:rgba(255,255,255,.08)}
#sheet .si.focus{background:none}

/* postavke: sekcije, teme */
.phone .sec{display:flex;align-items:center;margin:22px 12px 10px 2px;font-size:13px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;color:#a8a8b3}
.phone .sec svg{width:18px;height:18px;fill:var(--acc);margin-right:8px}
.phone .setting .lbl small{display:block;font-size:12px;color:#8e8e99;margin-top:3px;font-weight:400}
.phone .topics{display:flex;flex-wrap:wrap;margin:0 12px 6px 0}
.phone .topics .chip{height:44px;padding:0 10px 0 14px;margin:0 8px 8px 0}
.phone .topics .chip i{font-style:normal;font-size:18px;margin-left:8px;opacity:.6}
.phone .topics .addt{height:44px;width:140px;padding:0 14px;margin:0 8px 8px 0;border-radius:22px;border:1px dashed #4a4a55;background:none;color:#fff;font-size:14px}
.phone .topics .addt:focus{border-style:solid;border-color:#888;outline:0}
.phone .lbl2{font-size:12px;color:#8e8e99;margin:-4px 0 8px}
.phone .chanstrip{margin-bottom:18px}

/* player: lajkovi, SponsorBlock oznake, greška, ▶/❚❚ na sredini kad su kontrole vidljive */
#pvotes,#pstats{display:none}
.phone #pstats{display:block;margin-top:6px;font-size:12px;color:#c8c8d0}
.phone #pstats:empty{display:none}
.phone #pvotes{display:flex;margin-top:8px;font-size:12px;color:#c8c8d0}
.phone #pvotes:empty{display:none}
.phone #pvotes span{display:flex;align-items:center;margin-right:16px}
.phone #pvotes svg{width:16px;height:16px;fill:#c8c8d0;margin-right:6px}
.phone #osd-bar .sbm{position:absolute;top:0;bottom:0;background:#00d400;opacity:.85;pointer-events:none}
.phone #osd-bar .sbm.selfpromo{background:#ffff00}
.phone #osd-bar .sbm.interaction{background:#cc00ff}
.phone #player.osd #bigplay{opacity:1}
.phone #player.scrub #bigplay,.phone #player.mini #bigplay{opacity:0}
#perr{display:none}
.phone #perr{display:flex;flex-direction:column;align-items:center;justify-content:center;position:absolute;left:0;right:0;top:var(--sat);height:56.25vw;
  z-index:20;background:rgba(0,0,0,.85);padding:0 20px;text-align:center}
.phone #perr.hidden,.phone #player.mini #perr{display:none}
.phone #perr .et{font-size:14px;color:#eee;margin-bottom:14px}
.phone #perr button{height:44px;padding:0 18px;margin:0 6px;border-radius:22px;border:0;font-size:14px;background:#2a2a33;color:#fff}
.phone #perr .retry{background:#fff;color:#000;font-weight:600}

/* opšte: bez "rubber band" povlačenja, zamućena donja traka, AMOLED */
.phone,.phone body{overscroll-behavior:none}
.phone #view{overscroll-behavior-y:contain}
.phone #rail,.phone #rail.open{background:rgba(11,11,15,.85);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
@media (orientation:portrait) and (max-width:599px){
  .phone #hero .bg,.phone #hero .fade{height:48vw} /* kompaktan hero samo na uspravnom telefonu */
}
html.phone.amoled,html.phone.amoled body{background:#000}
.amoled #rail,.amoled #rail.open{background:rgba(0,0,0,.85)}
.amoled #hero .fade{background:linear-gradient(0deg,#000 0,rgba(0,0,0,.92) 12%,rgba(0,0,0,.5) 30%,rgba(0,0,0,0) 62%)}
.amoled .setting{background:#0e0e12}
@media (orientation:landscape){
  .phone #perr{top:0;height:100%}
  .phone #pvotes,.phone #pstats{display:none}
}
/* kanal-traka: razmak na kraju (zadnji kanal ne lijepi uz ivicu); veći dodirni ciljevi */
.phone .chanstrip .row{padding-right:16px}
.phone .card .more{width:44px;min-width:44px;height:44px}
.phone .card .cav{width:44px;height:44px;min-width:44px}
.phone .chanstrip .chan{flex:none;margin-right:12px}
/* meni: ručka je prava površina za povlačenje (ne samo crtica) */
#sheet .grabw{padding:8px 0 6px;touch-action:none}
#sheet .grab{margin:0 auto}
#sheet .sh{overscroll-behavior:contain}
.phone .navbtn svg{max-width:100%}

/* player: avatar + ime kanala (tap otvara kanal) */
.phone #pch{display:flex;align-items:center;margin-top:6px}
.phone #pch .pav{flex:none;width:28px;height:28px;margin-right:8px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:#fff}
.phone #pch .pav img{width:100%;height:100%;object-fit:cover;display:block}
.phone #pch #osd-author{margin-top:0;font-size:13px;font-weight:600;color:#e8e8ee}
.phone #pch #osd-author.lnk::after{content:" ›";opacity:.7}

/* swipe/pull-to-refresh */
.phone #ptr{position:fixed;top:calc(var(--sat,0px) - 40px);left:50%;width:40px;height:40px;margin-left:0;border-radius:50%;background:var(--card,#222);
  box-shadow:0 2px 10px rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;z-index:30;
  transform:translate(-50%,0)}
.phone #ptr svg{width:22px;height:22px;fill:#fff}
.phone #ptr.on{opacity:1}
.phone #ptr.go svg{fill:var(--acc,#ff4e45)}
.phone #ptr.spin svg{animation:ptrspin .7s linear infinite}
@keyframes ptrspin{to{transform:rotate(360deg)}}

.phone .chead{margin:18px 12px 14px 0}
.phone .chead .cav{margin-right:14px}
.phone .cav{width:64px;height:64px;font-size:28px}
.phone .cname{font-size:20px}
.phone .cmeta{font-size:13px;margin-top:3px}
.phone .cdesc{font-size:13px;margin-top:6px}

/* X za otkazivanje "Sljedeće" kartice: pojavi se pri povlačenju, magnet ga poveća */
.phone #upx{position:fixed;left:50%;bottom:calc(48px + var(--sab));width:56px;height:56px;margin-left:-28px;border-radius:50%;background:rgba(40,40,46,.92);display:flex;align-items:center;justify-content:center;z-index:40;box-shadow:0 4px 16px rgba(0,0,0,.5);transition:transform .15s,background .15s}
.phone #upx svg{width:26px;height:26px}
.phone #upx.hot{transform:scale(1.3);background:#e53935}
.phone #upnext{touch-action:none;z-index:35}

/* komentari */
.phone #pcm{margin:6px 12px 10px;padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.07);cursor:pointer;pointer-events:auto}
.phone #pcm:active{background:rgba(255,255,255,.12)}
.phone .cmh{font-size:14px;font-weight:600;margin-bottom:6px}
.phone .cmp{display:flex;align-items:center}
.phone .cmt{font-size:13px;color:#d6d6de;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;min-width:0}
.phone .cmt.off{color:#9e9ea7}
.phone .cav{flex:none;width:26px;height:26px;border-radius:50%;overflow:hidden;background:#2a2a33;margin-right:10px}
.phone .cav img{width:100%;height:100%;display:block}
#cmts{position:fixed;left:0;top:0;right:0;bottom:0;z-index:320;background:rgba(0,0,0,0);transition:background-color .2s}
#cmts.on{background:rgba(0,0,0,.55)}
#cmts .cbox{position:absolute;left:0;right:0;bottom:0;max-width:560px;margin:0 auto;height:78vh;display:flex;flex-direction:column;background:#1c1c22;border-radius:16px 16px 0 0;
  transform:translateY(100%);transition:transform .22s ease-out;padding-bottom:var(--sab)}
#cmts.on .cbox{transform:none}
#cmts .grabw{padding:8px 0 6px;touch-action:none;flex:none}
#cmts .grab{width:36px;height:4px;border-radius:2px;background:#4a4a55;margin:0 auto}
#cmts .cmh{padding:0 16px 10px;margin:0;border-bottom:1px solid var(--line);flex:none;font-size:15px;font-weight:600}
#cmts .clist{flex:1;overflow-y:auto;overscroll-behavior:contain;padding:6px 0 16px}
#cmts .cm{display:flex;padding:8px 16px}
#cmts .cm .cav{width:34px;height:34px}
#cmts .cb{min-width:0;flex:1}
#cmts .ch{font-size:12px;color:#9e9ea7}
#cmts .ch b{color:#ececf1;margin-right:6px;font-weight:600}
#cmts .ch b.own{background:rgba(255,255,255,.18);border-radius:8px;padding:0 6px}
#cmts .ct{font-size:14px;line-height:19px;margin-top:2px;white-space:pre-wrap;word-wrap:break-word;color:#ececf1}
#cmts .cf{font-size:12px;color:#9e9ea7;margin-top:4px}
#cmts .crb{font-size:13px;color:#7fb5ff;margin-top:6px;padding:10px 0;font-weight:600}
#cmts .crl .cm{padding:8px 0 4px}
#cmts .crl .cm .cav{width:24px;height:24px}

