    'x.open(m.method,m.url,true);x.responseType=m.type;x.timeout=m.timeout;' +
    'Object.keys(m.headers).forEach(function(k){x.setRequestHeader(k,m.headers[k])});' +
    'var d=function(o){o.id=m.id;parent.postMessage(o,"*")};' +
    'x.onload=function(){d({s:x.status,r:x.response})};' +
    'x.onerror=function(){d({err:"net"})};x.ontimeout=function(){d({err:"timeout"})};' +
    'x.send(m.body||null)});parent.postMessage({ready:1},"*");<\/script>';

