/* Titlovi: dohvat originalnog tracka (timedtext XML) + prijevod na ciljni jezik preko Google Translate gtx.
   YouTube-ov vlastiti tlang=bs traži PO token (429), a native TV app bosanski uopće ne nudi. */
var Subs = (function () {
  // orig = jezik originalnog zvuka; uz AI dubbing YouTube ima auto-titlove na 20 jezika, a samo originalni je tačan
  function pickTrack(tracks, lang, orig) {
    if (!tracks.length) return null;
