      if (srv1) { dec.innerHTML = text; text = dec.value; }
      text = text.replace(/\s*\n\s*/g, ' ').replace(/\s+/g, ' ').trim();
      if (!text) continue;
      var t = srv1 ? +p.getAttribute('start') : +p.getAttribute('t') / 1000;
      var d = srv1 ? +p.getAttribute('dur') : +p.getAttribute('d') / 1000;
      cues.push({ s: t, e: t + (d || 3), text: text });
    }
    // ASR "rolling" titlovi se preklapaju: skrati kraj na početak sljedećeg
    for (i = 0; i < cues.length - 1; i++) if (cues[i].e > cues[i + 1].s) cues[i].e = Math.max(cues[i].s + 0.4, cues[i + 1].s);
    return cues;
  }

  function parseVtt(txt) {
    var cues = [], blocks = txt.replace(/\r/g, '').split(/\n\n+/);
    blocks.forEach(function (b) {
      var m = b.match(/(\d+):(\d\d):(\d\d)\.(\d+) --> (\d+):(\d\d):(\d\d)\.(\d+)/);
      if (!m) return;
      var s = +m[1] * 3600 + +m[2] * 60 + +m[3] + +('0.' + m[4]);
      var e = +m[5] * 3600 + +m[6] * 60 + +m[7] + +('0.' + m[8]);
      var text = b.split('\n').slice(1).join(' ').replace(/<[^>]+>/g, '').trim();
