        value: mode === 'off' ? 'Isključeni' : mode === 'translate' ? 'Prijevod ' + lang.toUpperCase() : 'Original' + origLang,
        opts: [{ v: 'translate', l: 'Prijevod na ' + (LANG_NAMES[lang] || lang) }, { v: 'original', l: 'Original' + origLang }, { v: 'off', l: 'Isključeni' }],
        set: setSubs },
      { icon: 'lang', label: 'Jezik prijevoda', cur: lang, value: LANG_NAMES[lang] || lang,
        opts: SUB_LANGS.map(function (l) { return { v: l, l: LANG_NAMES[l] || l }; }), set: setSubsLang },
      { icon: 'hd', label: 'Kvalitet', cur: state.h, value: state.quality || '…',
        opts: audioMode ? [{ v: 0, l: 'Zvuk (automatski)' }] : heights().map(function (h) { return { v: h, l: h + 'p' + (h >= 2160 ? '  4K' : h >= 1440 ? '  2K' : h >= 720 ? '  HD' : '') }; }), set: setQuality },
      { icon: 'speed', label: 'Brzina', cur: state.rate, value: state.rate + 'x',
        opts: [0.75, 1, 1.25, 1.5, 2].map(function (r) { return { v: r, l: r === 1 ? 'Normalno' : r + 'x' }; }), set: setRate }
      , { icon: 'timer', label: 'Tajmer', cur: sleepAt ? sleepLeft() : 0, value: sleepAt ? sleepLeft() + ' min' : 'Isključen',
