  /* telefon -> TV: Android šalje video i trenutnu poziciju TizenTube aplikaciji na TV-u */
  function castToTv() {
    if (!info) return;
    if (castOn) { toast('Već svira na TV-u', 3000); return; }
    castId = info.id; // da potvrda s TV-a ne pauzira neki drugi video otvoren u međuvremenu
    toast('Šaljem na TV…', 30000);
    clearTimeout(castTimer);
    castTimer = setTimeout(function () { toast('TV se ne javlja (provjeri je li upaljen i na istom WiFi-ju)', 6000); }, 45000);
    try {
      Android.cast(JSON.stringify({ id: info.id, title: info.title, author: info.author,
        t: info.live ? 0 : Math.floor(nowPos()) }));
    } catch (e) { clearTimeout(castTimer); toast('Greška: ' + e.message, 6000); }
  }
  var castTimer, castId;
  window.ttCastStep = function (msg) { toast(msg, 30000); };
  window.ttCastDone = function (ok, msg) {
    clearTimeout(castTimer);
    toast(ok ? 'Pušteno na TV-u' : 'TV: ' + msg, ok ? 4000 : 8000);
    if (ok && info && info.id === castId) {
      castOn = true;
      pauseByUser(); // TV svira: telefon ne smije držati ni zvuk ni servis, a pauza mora ostati pauza
