  };

  function renderCtl() {
    var list = controls(), h = list.map(function (c, i) {
      var cls = 'pc' + (ctl.on && i === ctl.i ? (ctl.menu ? ' open' : ' focus') : '');
      return '<div class="' + cls + '" data-i="' + i + '">' + iconSvg(c.icon) + '<span><small>' + c.label + '</small>' + c.value + '</span></div>';
    }).join('');
    if (ctl.menu) {
      var c = list[ctl.i];
      h += '|' + ctl.mi + c.opts.map(function (o, j) {
        return '<div class="mi' + (j === ctl.mi ? ' focus' : '') + (o.v === c.cur ? ' sel' : '') + '" data-j="' + j + '">' + o.l + '</div>';
      }).join('');
    }
    if (h === ctl.html) return;
    ctl.html = h;
    var parts = h.split('|');
    $('pctl').innerHTML = parts[0];
    var m = $('pmenu');
    if (!ctl.menu) { m.classList.add('hidden'); return; }
    m.innerHTML = '<div class="mh">' + list[ctl.i].label + '</div>' + parts[1].replace(/^\d+/, '');
    m.style.left = $('pctl').children[ctl.i].offsetLeft + 'px';
    m.classList.remove('hidden');
  }

  function openMenu(i) {
    var c = controls()[i];
    if (c.action) { ctl.on = true; ctl.i = i; ctl.menu = false; renderCtl(); c.action(); return; }
    ctl.on = true; ctl.i = i; ctl.menu = true;
    ctl.mi = 0;
    c.opts.forEach(function (o, j) { if (o.v === c.cur) ctl.mi = j; });
    renderCtl();
  }

  function pickMenu(j) {
    var c = controls()[ctl.i];
    ctl.menu = false;
    if (c.opts[j]) c.set(c.opts[j].v);
