      n = controls()[ctl.i].opts.length;
      if (code === 38) ctl.mi = (ctl.mi + n - 1) % n;
      else if (code === 40) ctl.mi = (ctl.mi + 1) % n;
      else if (code === 13) { pickMenu(ctl.mi); return true; }
      else if (code === 37 || code === 10009 || code === 27 || code === 8) ctl.menu = false;
      else return false;
