    if (code === 37) ctl.i = Math.max(0, ctl.i - 1);
    else if (code === 39) ctl.i = Math.min(controls().length - 1, ctl.i + 1);
    else if (code === 13 || code === 38) { openMenu(ctl.i); return true; }
    else if (code === 40 || code === 10009 || code === 27 || code === 8) {
      closeCtl();
      return code === 40 || !ANDROID; // telefon: fokus kontrola se ne vidi, pa BACK odmah ide dalje (mini player)
    }
    else return false;
    renderCtl();
    return true;
  }

  function togglePlay() {
    if (castOn) { toast('Svira na TV-u', 3000); showOsd(); return; } // ne pokreći drugi zvuk na telefonu
    if (video.paused) { userPause = false; playSafe(); }
    else { userPause = true; video.pause(); }
