  function onKey(code) {
    if ($('cmts') && (code === 10009 || code === 27 || code === 8)) { closeComments(); return true; }
    if (upNextOn()) {
      if (code === 13) { playNext(); return true; }
      if (code === 10009 || code === 27 || code === 8) { upCancel = true; hideUpNext(); return true; }
    }
    if (ctl.on) {
      showOsd();
      if (ctlKey(code)) return true;
    }
    if (scrub.t >= 0) {
      if (code === 13) { commitScrub(); return true; }
      if (code === 10009 || code === 27 || code === 8) { cancelScrub(); return true; }
    }
    if (code >= 48 && code <= 57) { // 0-9: skok na 0%-90%
      seekTo(duration() * (code - 48) / 10);
      return true;
    }
    if (info && info.live && (code === 39 || code === 417)) { goLive(); return true; }
    switch (code) {
      case 38: case 40:
        ctl.on = true; ctl.menu = false;
        showOsd(); renderCtl(); return true;
      case 13: case 10252:
        togglePlay(); return true;
      case 415: userPause = false; playSafe(); showOsd(); return true;
      case 19: pauseByUser(); showOsd(); return true;
      case 37: case 412: seekBy(-10); return true;
      case 39: case 417: seekBy(10); return true;
      case 403: cycleSubs(); showOsd(); return true;
      case 404: cycleSubsLang(); showOsd(); return true;
      case 405: cycleQuality(); showOsd(); return true;
      case 406: setRate(RATES[(RATES.indexOf(state.rate) + 1) % RATES.length]); showOsd(); return true;
      case 10009: case 27: case 8:
        if (ANDROID) { setMini(true); return true; } // telefon: nazad = mini player, kao YouTube
        close(); return true;
      case 413: close(); return true;
      case 10233: case 427: playNext(); return true; // MediaTrackNext / ChannelUp
