  }

  /* klik mišem: na "Sljedeće" kartici pusti odmah, inače pauza */
  function onClick(t, e) {
    var c = t && t.closest ? t : null, had = $('player').classList.contains('osd');
    if (mini) { miniClick(c); return; }
    showOsd();
    if (ANDROID && c && c.closest('#pch')) openChannel();
    else if (c && c.closest('#perr .retry')) { if (cur) open(cur, true); }
    else if (c && c.closest('#perr .cls')) close();
    else if (c && c.id === 'cmts') closeComments();
    else if (c && c.closest('#cmts .crb')) c.closest('.crb')._fn();
    else if (c && c.closest('#pcm') && cm && cm.items.length) openComments();
    else if (c && c.closest('#upnext')) playNext();
    else if (c && c.closest('#prel .ri')) open(rel[+c.closest('.ri').getAttribute('data-k')]);
    else if (c && c.closest('#osd-bar') && e) { cancelScrub(); seekTo(barTime(e)); }
    else if (c && c.closest('#pmenu .mi')) pickMenu(+c.closest('.mi').getAttribute('data-j'));
    else if (c && c.closest('#pctl .pc')) {
      var i = +c.closest('.pc').getAttribute('data-i');
      if (ctl.menu && ctl.i === i) { ctl.menu = false; renderCtl(); } else openMenu(i);
    } else if (ctl.menu) { ctl.menu = false; renderCtl(); }
    else if (c && c.closest('#pwrap')) return;
    else if (ANDROID && portrait() && e && e.clientY > $('video').getBoundingClientRect().bottom) return; // tap ispod videa
    // telefon: tap pokaže kontrole; kad su vidljive, tap na sredinu (▶/❚❚) je pauza, drugdje ih sakrije (kao YouTube)
    else if (ANDROID) {
