      if ($('player').classList.contains('osd') && e.target.closest && e.target.closest('#osd-bar,#pwrap,#bigplay')) showOsd();
    }, { passive: true });
    video.addEventListener('pause', bgState);
    // telefon: sistem/Chromium pauzira WebView kad stranica postane hidden; pauzu koju je tražio
    // korisnik (dugme/notifikacija, pauseByUser) poštujemo, sistemsku poništavamo
    video.addEventListener('pause', resumeAfterHiddenPause);
    document.addEventListener('visibilitychange', handleVisibility);
    // mreža se vratila: odmah nastavi od iste pozicije umjesto da čekaš sljedeći backoff
    window.addEventListener('online', function () {
      if (!isOpen()) return;
      if (bgNetBack()) return; // ekran ugašen: nastavi pozadinski zvuk bez korisnika
      if (!info) {
        // otvaranje je palo zbog mreže: sam pokušaj ponovo (Retry dugme ostaje kao alternativa)
        if (errNet && cur && $('perr') && !$('perr').classList.contains('hidden')) {
          errNet = false; hideErr(); open(cur, true);
        }
        return;
      }
      if (netRetry.n > 0 || netRetry.t != null) {
        clearTimeout(netRetry.timer);
        netRetry.n = 0;
        toast('Mreža vraćena', 2500);
        hideErr();
        // auto-spušten kvalitet (slowTick) ne smije ostati zauvijek poslije prekida; ručni izbor važi
        if (!qualityOverride) capH = 0;
        startPlayback(netRetry.t != null ? netRetry.t : curPos());
        netRetry.t = null;
      }
    });
    video.addEventListener('error', function () {
      if (!isOpen() || !info) return;
      dbg('video error ' + (video.error && video.error.code) + ' engine=' + !!engine);
      // code 2 = mrežna greška: ne pada na 360p/nije zatvaraj, sačekaj mrežu
      if (!info.live && video.error && video.error.code === 2) {
        netWait(curPos());
        stopEngine();
        return;
      }
      if (engine) {
        var t = video.currentTime;
        stopEngine();
        toast('Greška u reprodukciji, prelazim na osnovnu kvalitetu');
        if (info.live) { if (info.hls) startHls(); } else startProgressive(t);
      } else if (audioMode) { // audio URL nije prošao (403/PO token): isti video, običnim putem
        audioMode = false;
        $('player').classList.remove('audio');
        video.removeAttribute('poster');
        startMse(video.currentTime || 0);
      } else if (ANDROID) { setSpinner(false); showErr(video.error && video.error.code === 2 ? 'mrežna greška' : ''); }
      else toast('Greška u reprodukciji', 4000);
    });
    video.addEventListener('seeking', function () { if (engine) engine.seek(video.currentTime); });
    $('player').addEventListener('mousemove', function (e) {
      if (!isOpen()) return;
      showOsd();
      var onBar = e.target && e.target.closest && e.target.closest('#osd-bar');
      if (onBar && canSeek()) showPreview(barTime(e));
      else if (scrub.t < 0) hidePreview();
    });
    setInterval(renderTick, 250);
  }

  // isOpen prema van = player preko cijelog ekrana (prima tipke/klikove); mini player ne smeta ostatku aplikacije
  return { hold: hold, zoom: zoom, init: init, open: open, close: close, isOpen: isFull, isMini: isMini, mini: setMini, onKey: onKey, onClick: onClick,
    barDrag: barDrag, cancelNext: cancelNext, session: session, bgWanted: bgWanted };
})();

