/* Navigacija daljinskim: bočni meni (#rail), horizontalni redovi (.row) i mreže; skrolanje stranice i redova.
   Pozicije se računaju iz offsetTop/Left (ne getBoundingClientRect), pa su tačne i dok animacija još traje. */
var Nav = (function () {
  var cur = null, scrollY = 0, lastContent = null;
  var VIEW_X = 120, VIEW_W = 1800, VIEW_H = 1080;

  function inRail(e) { return !!e.closest('#rail'); }

  /* konačna pozicija elementa na ekranu (nakon što se transformacije završe) */
  function rect(e) {
    var page = e.closest('.page');
    if (!page) { var r = e.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; }
    var x = 0, y = 0, n = e;
    while (n && n !== page) { x += n.offsetLeft; y += n.offsetTop; n = n.offsetParent; }
    var row = e.closest('.row');
    if (row) x -= row._x || 0;
    return { x: VIEW_X + page.offsetLeft + x, y: y - scrollY, w: e.offsetWidth, h: e.offsetHeight };
  }

  function visible(e) {
    if (!e.offsetWidth || e.closest('.hidden')) return false;
    if (inRail(e)) return true;
    var r = rect(e);
    return r.x >= VIEW_X + 10 && r.x < VIEW_X + VIEW_W - 60; // red: samo kartice koje se vide
  }

  function cands() {
    return Array.prototype.filter.call(document.querySelectorAll('.f'), visible);
  }

  function center(r) { return { x: r.x + r.w / 2, y: r.y + r.h / 2 }; }

  function focus(e, noReveal) {
    if (!e) return;
    if (cur) cur.classList.remove('focus');
    cur = e;
    e.classList.add('focus');
    $('rail').classList.toggle('open', inRail(e));
    if (!inRail(e)) lastContent = e;
    if (document.activeElement && document.activeElement.tagName === 'INPUT') document.activeElement.blur();
    if (!noReveal) reveal(e); // miš: ne skroluj ispod kursora
    nearEnd(e);
  }

  /* beskonačne liste: red/mreža s _more() učitava još kad se fokus približi kraju */
  function nearEnd(e) {
    var box = e.closest('.row, .grid');
    if (!box || !box._more) return;
    var items = box.children, n = items.length, i = Array.prototype.indexOf.call(items, e.closest('.row > *, .grid > *'));
    if (i >= 0 && i >= n - (box.classList.contains('row') ? 6 : 12)) box._more();
  }

  function page() { return document.querySelector('.page'); }

  function setY(y) {
    var p = page();
    if (!p) return;
    var max = Math.max(0, p.offsetHeight - VIEW_H + 40);
    scrollY = Math.max(0, Math.min(max, y));
    p.style.transform = 'translateY(' + (-scrollY) + 'px)';
  }

  /* točkić / air mouse scroll */
  function scrollBy(d) {
    setY(scrollY + d);
    var p = page(), grids = p ? p.querySelectorAll('.grid') : [], g = grids[grids.length - 1];
    if (g && g._more && scrollY > p.offsetHeight - VIEW_H * 2.5) g._more();
  }

  function setRowX(row, x) {
    var wrap = row.parentNode;
    var max = Math.max(0, row.scrollWidth - wrap.clientWidth + 60);
    row._x = Math.max(0, Math.min(max, x));
    row.style.transform = 'translateX(' + (-row._x) + 'px)';
  }

  function scrollRow(row, dir) {
    setRowX(row, (row._x || 0) + dir * 760);
    if (dir > 0 && row._more && row._x > row.scrollWidth - row.parentNode.clientWidth - 1600) row._more();
  }

  function reveal(e) {
    var p = e.closest('.page');
    if (!p) return;
    var row = e.closest('.row');
    if (row) {
      // fokusirana kartica ostaje blizu lijevog ruba, prethodna malo viri
      var off = e.offsetLeft - (row.firstElementChild ? row.firstElementChild.offsetLeft : 0);
      setRowX(row, off > 0 ? off - 70 : 0);
    }
    var r = rect(e), top = r.y + scrollY, shelf = e.closest('.shelf');
    if (top + r.h < VIEW_H - 120 && (!shelf || top < 700)) { setY(0); return; }
    if (row && shelf) { setY(rect(shelf).y + scrollY - 60); return; } // red "uskoči" na fiksnu visinu
    if (r.y + r.h > VIEW_H - 50) setY(scrollY + r.y + r.h - VIEW_H + 80);
    else if (r.y < 40) setY(scrollY + r.y - 80);
  }

  function resetScroll() {
    scrollY = 0;
    lastContent = null;
    var p = page();
    if (p) p.style.transform = '';
    $('view').scrollTop = 0; // telefon: nativni scroll
  }

  function sibling(e, dir) {
    var n = e;
    do { n = dir === 'left' ? n.previousElementSibling : n.nextElementSibling; } while (n && !n.classList.contains('f'));
    return n;
  }

  function spatial(list, dir) {
    var c = center(rect(cur)), best = null, bs = 1e9;
    list.forEach(function (e) {
      if (e === cur) return;
      var p = center(rect(e)), dx = p.x - c.x, dy = p.y - c.y, main, side;
      if (dir === 'left') { main = -dx; side = Math.abs(dy); }
      else if (dir === 'right') { main = dx; side = Math.abs(dy); }
      else if (dir === 'up') { main = -dy; side = Math.abs(dx); }
      else { main = dy; side = Math.abs(dx); }
      if (main <= 4) return;
      // gore/dolje: preferiraj elemente koji počinju lijevo (kao YouTube TV)
      var score = main + side * (dir === 'up' || dir === 'down' ? 0.6 : 2.5);
      if (score < bs) { bs = score; best = e; }
    });
    return best;
  }

  function railSel() { return document.querySelector('.navbtn.sel') || document.querySelector('.navbtn'); }

  function move(dir) {
    var list = cands();
    if (!cur || !document.body.contains(cur) || !visible(cur) && !cur.closest('.row')) {
      focus(list.filter(function (e) { return !inRail(e); })[0] || list[0]);
      return;
    }
    if (inRail(cur)) {
      if (dir === 'right') {
        var back = lastContent && document.body.contains(lastContent) ? lastContent : list.filter(function (e) { return !inRail(e); })[0];
        if (back) focus(back);
        return;
      }
      if (dir === 'left') return;
      var b = spatial(list.filter(inRail), dir);
      if (b) focus(b);
      return;
    }
    if (cur.closest('.row') && (dir === 'left' || dir === 'right')) {
      var s = sibling(cur, dir);
      if (s) focus(s);
      else if (dir === 'left') focus(railSel());
      return;
    }
    var best = spatial(list.filter(function (e) { return !inRail(e); }), dir);
    if (best) focus(best);
    else if (dir === 'left') focus(railSel());
  }

  function current() { return cur; }

  function setViewH(h) { VIEW_H = h; }

  return { focus: focus, move: move, current: current, resetScroll: resetScroll, cands: cands,
    scrollBy: scrollBy, scrollRow: scrollRow, setRowX: setRowX, setViewH: setViewH };
})();

