  var TOPICS = ['Muzika', 'Sevdah', 'Vijesti', 'Sport', 'Dokumentarci', 'Podcast', 'Gaming', 'Humor', 'Kuhanje', 'Putovanja'];
  // engleski upit za iste teme/žanrove: čip prikazuje prevedeni naziv, ali pretraga mora ići na jeziku UI-ja
  var QUERY_EN = {
    'Muzika': 'Music', 'Vijesti': 'News', 'Dokumentarci': 'Documentaries', 'Humor': 'Comedy',
    'Kuhanje': 'Cooking', 'Putovanja': 'Travel', 'Top hitovi': 'Top hits', 'Elektronska': 'Electronic',
    'Trening': 'Workout', 'Klasika': 'Classical', 'Narodna': 'Balkan folk'
  };
  function topicQuery(t) { return UI_EN ? (QUERY_EN[t] || t) : t; }

  /* ---------- popravka lokalnih podataka ----------
     localStorage može imati stari/pokvareni tip (npr. history:"oops") i tada bi init()
     pao prije nego što window.ttBack postoji. Svaki ključ se provjerava i vraća na default. */
  var SETTINGS_DEFAULTS = {
    maxHeight: 1080, updChk: 0,
    subs: 'translate', subLang: UI_EN ? 'en' : 'bs', uiLang: 'auto',
    shelves: UI_EN ? 'Music 2026, Trending news, Documentaries, Gaming, Podcasts' : 'Sevdah, Balkan vijesti danas, Muzika 2026, Dokumentarci sa prijevodom',
    autoplay: true, bg: true, histRec: true, sb: true, ryd: true, amoled: false
  };
  function plainObj(v) { return !!v && typeof v === 'object' && !Array.isArray(v); }
  function validEntry(v) { return plainObj(v) && typeof v.id === 'string' && !!v.id; }

  function repairSettings() {
    var D = SETTINGS_DEFAULTS;
    if (Settings.get('maxHeight') !== undefined && [360, 480, 720, 1080, 1440, 2160].indexOf(Settings.get('maxHeight')) < 0) Settings.set('maxHeight', D.maxHeight);
    if (Settings.get('updChk') !== undefined && (typeof Settings.get('updChk') !== 'number' || !isFinite(Settings.get('updChk')) || Settings.get('updChk') < 0)) Settings.set('updChk', D.updChk);
    ['autoplay', 'bg', 'histRec', 'sb', 'ryd', 'amoled'].forEach(function (key) {
      var x = Settings.get(key);
      if (x !== undefined && typeof x !== 'boolean') Settings.set(key, D[key]);
    });
    if (Settings.get('subs') !== undefined && ['off', 'original', 'translate'].indexOf(Settings.get('subs')) < 0) Settings.set('subs', D.subs);
    if (Settings.get('subLang') !== undefined && ['bs', 'hr', 'sr', 'en', 'de'].indexOf(Settings.get('subLang')) < 0) Settings.set('subLang', D.subLang);
    if (Settings.get('uiLang') !== undefined && ['auto', 'en', 'bs'].indexOf(Settings.get('uiLang')) < 0) Settings.set('uiLang', D.uiLang);
    if (Settings.get('shelves') !== undefined && typeof Settings.get('shelves') !== 'string') Settings.set('shelves', D.shelves);
    // nizovi: zadrži ispravne stavke, odbaci pokvarene
    [['history', validEntry], ['later', validEntry],
      ['hidden', function (x) { return typeof x === 'string' && !!x; }],
      ['searches', function (x) { return typeof x === 'string'; }]
    ].forEach(function (p) {
      var a = Settings.get(p[0]);
      if (a === undefined) return;
      if (!Array.isArray(a)) { Settings.set(p[0], []); return; }
      var out = a.filter(p[1]);
      if (out.length !== a.length) Settings.set(p[0], out);
    });
    // objekti (pozicije, brojači slušanja, avatari, visitor): moraju biti plain objekat
    ['pos', 'avatars', 'visitor2'].forEach(function (key) {
      var x = Settings.get(key);
      if (x !== undefined && !plainObj(x)) Settings.set(key, {});
    });
    var pl = Settings.get('plays');
    if (pl !== undefined) {
      if (!plainObj(pl)) Settings.set('plays', {});
      else {
        var out = {}, changed = false;
        Object.keys(pl).forEach(function (id) {
          var e = pl[id];
          if (plainObj(e) && plainObj(e.v) && typeof e.v.id === 'string') out[id] = e; else changed = true;
        });
        if (changed) Settings.set('plays', out);
      }
    }
  }

  function filterHidden(list, hid) {
    hid = hid || {};
    return (list || []).filter(function (v) { return v && !hid[v.id]; });
  }
  function laterLabel(n) { return 'Gledaj kasnije' + (n ? ' · ' + n : ''); }

  /* ---------- gradivni blokovi ---------- */
  function progressOf(id) {
    var p = (Settings.get('pos') || {})[id];
    return p && p.d ? p.t / p.d : 0;
  }

  // neke stavke (npr. cast s telefona) nemaju thumb; izvedi ga iz id-a da ne ostane prazna sličica
  function thumbOf(v) { return v.thumb || 'https://i.ytimg.com/vi/' + v.id + '/mqdefault.jpg'; }

  /* ---------- metapodaci na jeziku UI-ja (F10) ----------
     YouTube vraća "2,4 mil. pregleda · prije 1 god." na jeziku sa kojim je učitan feed.
     Historija zato čuva i sirove brojeve (views/age), a stari zapisi se prevode pri prikazu. */
  var AGE_UNITS = [[/sekund|second|\bs\b/i, 1], [/minut|minute|\bmin\b/i, 60], [/sat|hour|\bhr\b|\bh\b/i, 3600],
    [/dan|day|\bd\b/i, 86400], [/sedmic|week|\bwk\b|\bw\b/i, 604800],
    [/mjesec|mesec|mj\.|month|\bmo\b/i, 2592000], [/godin|god\.|year|\byr\b|\by\b/i, 31536000]];

  /* "2,4 mil." / "4.5M" / "1.059 pregleda" -> broj; bez jedinice/oznake pregleda vraća null */
  function parseViews(s) {
    s = String(s || '');
    var m = /([\d.,]+)\s*(mlrd|mil\.?|hilj\.?|b|m|k)\b/i.exec(s);
    var mult = 1, num;
    if (m) {
      num = m[1];
      mult = /mlrd|^b$/i.test(m[2]) ? 1e9 : /mil|^m$/i.test(m[2]) ? 1e6 : 1e3;
    } else {
      if (!/pregleda|views|gledanja/i.test(s)) return null;
      m = /([\d.,]+)/.exec(s);
      if (!m) return null;
      num = m[1];
      // bez jedinice: "1.059" je hiljada, "1,5" je decimalni zarez
      if (/^\d{1,3}(?:\.\d{3})+$/.test(num)) num = num.replace(/\./g, '');
      else num = num.replace(',', '.');
    }
    if (mult > 1) {
      if (/^\d{1,3}(?:[.,]\d{3})+$/.test(num)) num = num.replace(/[.,]/g, ''); // 1.234 mil.
      else num = num.replace(',', '.');
    }
    var n = parseFloat(num);
    return isFinite(n) ? Math.round(n * mult) : null;
  }

  /* "prije 1 god." / "5y ago" / "3 days ago" -> sekunde */
  function ageFromText(t) {
    var m = /(\d+)\s*([A-Za-zčćžšđČĆŽŠĐ.]+)/.exec(String(t || ''));
    if (!m) return null;
    for (var i = 0; i < AGE_UNITS.length; i++) if (AGE_UNITS[i][0].test(m[2])) return +m[1] * AGE_UNITS[i][1];
    return null;
  }

  function ageText(sec) {
    if (!sec || !isFinite(sec)) return '';
    var u = [[31536000, 'year', 'god.'], [2592000, 'month', 'mj.'], [604800, 'week', 'sedm.'],
      [86400, 'day', 'dan'], [3600, 'hour', 'sat'], [60, 'minute', 'min'], [1, 'second', 's']];
    for (var i = 0; i < u.length; i++) {
      if (sec < u[i][0]) continue;
      var n = Math.max(1, Math.round(sec / u[i][0]));
      if (UI_EN) return n + ' ' + u[i][1] + (n === 1 ? '' : 's') + ' ago';
      if (i === 3) return 'prije ' + n + ' ' + (n === 1 ? 'dan' : 'dana');
      if (i === 4) return 'prije ' + n + ' ' + (n === 1 ? 'sat' : n < 5 ? 'sata' : 'sati');
      return 'prije ' + n + ' ' + u[i][2];
    }
    return '';
  }

  /* meta za karticu/hero: sirovi views/age ako postoje, inače parsiranje starog stringa */
  function metaLocal(v) {
    if (!v) return '';
    var src = String(v.meta || '');
    if (!src) return '';
    var parts = src.split(' · ');
    var views = typeof v.views === 'number' ? v.views : null;
    var age = typeof v.age === 'number' && v.age < 1e10 ? v.age : null;
    var vp = 0, ap = 0;
    if (parts.length > 1) { vp = parts[0]; ap = parts.slice(1).join(' · '); }
    else if (views == null && parseViews(parts[0]) != null) vp = parts[0];
    else if (age == null && ageFromText(parts[0]) != null) ap = parts[0];
    if (views == null) views = parseViews(vp);
    if (age == null) age = ageFromText(ap);
    if (age != null && v.at && Date.now() > v.at) age += (Date.now() - v.at) / 1000;
    var out = [];
    if (views != null) out.push(fmtCount(views) + (UI_EN ? ' views' : ' pregleda'));
    else if (vp) out.push(vp);
    if (age != null) out.push(ageText(age));
    else if (ap) out.push(ap);
    return out.length ? out.join(' · ') : src;
  }

  function card(v) {
    var c = el('div', 'f card');
    var th = el('div', 'th');
    var img = el('img');
    img.src = thumbOf(v);
    img.alt = '';
    img.loading = 'lazy';
    img.decoding = 'async';
    th.appendChild(img);
    if (v.length) th.appendChild(el('div', 'd', v.length));
    else if (v.live) th.appendChild(el('div', 'd live', 'UŽIVO'));
    c._vid = v.id;
    c.appendChild(th);
    setProgress(c);
    if (ANDROID) phoneMeta(c, v);
    else {
      c.appendChild(el('div', 't', v.title));
      c.appendChild(el('div', 'm', [v.author, v.meta].filter(Boolean).join(' · ')));
    }
    c.onclick = function () {
      if (page === 'music') { v.audio = true; countPlay(v); } // pjesma = samo zvuk
      Player.open(v);
    };
    return c;
  }

  /* Muzika: brojač slušanja za police "Nedavno slušano" i "Najslušanije" */
  function countPlay(v) {
    var pl = Settings.get('plays') || {}, e = pl[v.id] || { n: 0 };
    e.n++; e.at = Date.now();
    e.v = { id: v.id, title: v.title, author: v.author, channelId: v.channelId || '', thumb: v.thumb, length: v.length, meta: '', avatar: v.avatar || '' };
    pl[v.id] = e;
    var ids = Object.keys(pl);
    if (ids.length > 150) ids.sort(function (a, b) { return pl[b].at - pl[a].at; }).slice(150).forEach(function (k) { delete pl[k]; });
    Settings.set('plays', pl);
  }
  function playedList(byCount) {
    var pl = Settings.get('plays') || {};
    return Object.keys(pl).map(function (k) { return pl[k]; })
      .sort(function (a, b) { return byCount ? b.n - a.n || b.at - a.at : b.at - a.at; })
      .map(function (e) { return e.v; });
  }

  /* telefon: avatar kanala | naslov + autor · meta | ⋮ (kao YouTube) */
  function phoneMeta(c, v) {
    var row = el('div', 'cr'), tx = el('div', 'tx');
    if (v.channelId) {
      var av = avatarEl(v.channelId, v.author, v.avatar, 'f cav');
      av.onclick = function () { showChannel(v.channelId, v.author, here()); };
      row.appendChild(av);
    }
    tx.appendChild(el('div', 't', v.title));
    tx.appendChild(el('div', 'm', [v.author, metaLocal(v)].filter(Boolean).join(' · ')));
    row.appendChild(tx);
    var more = el('button', 'f more');
    more.innerHTML = iconSvg('more');
    more.title = 'Više opcija';
    more.setAttribute('aria-label', 'Više opcija');
    if (v.title) { // čitač ekrana kaže i o kojem videu je riječ
      more.title = 'Više opcija: ' + v.title;
      more.setAttribute('aria-label', more.title);
    }
    more.onclick = function () { cardMenu(v, c); };
    row.appendChild(more);
    c.appendChild(row);
    c._menu = function () { cardMenu(v, c); }; // dugi pritisak (mobile.js)
  }

  /* avatari kanala: pamte se po id-u kanala (iz feedova, pretrage, stranice kanala) */
  var avMem = null, avT = 0;
  function cachedAvatar(id) { if (!avMem) avMem = Settings.get('avatars') || {}; return avMem[id]; }
  function noteAvatar(id, url) {
    if (!id || !url || cachedAvatar(id) === url) return;
    if (Object.keys(avMem).length > 600) avMem = {};
    avMem[id] = url;
    clearTimeout(avT);
    avT = setTimeout(function () { Settings.set('avatars', avMem); }, 1500);
  }
  function avatarEl(id, name, url, cls) {
    var av = el('div', cls);
    url = url || cachedAvatar(id);
    if (url) {
      noteAvatar(id, url);
      var im = el('img');
      im.src = url; im.alt = ''; im.loading = 'lazy';
      av.appendChild(im);
    } else av.textContent = (name || '?').charAt(0).toUpperCase();
    av.style.background = 'hsl(' + ((id || '').charCodeAt(5) || 7) * 37 % 360 + ',45%,35%)';
    return av;
  }

  /* ---------- telefon: "Gledaj kasnije", "Ne zanima me", donji meni ---------- */
  function later() { return Settings.get('later') || []; }
  function inLater(id) { return later().some(function (x) { return x.id === id; }); }
  function toggleLater(v) {
    var had = inLater(v.id), l = later().filter(function (x) { return x.id !== v.id; });
    if (!had) l.unshift({ id: v.id, title: v.title, author: v.author, channelId: v.channelId || '', thumb: thumbOf(v), length: v.length, meta: v.meta, views: v.views, age: v.age });
    Settings.set('later', l.slice(0, 200));
    toast(had ? 'Uklonjeno iz „Gledaj kasnije”' : 'Sačuvano u „Gledaj kasnije”');
  }
  function hiddenMap() {
    var m = {}, h = Settings.get('hidden');
    if (Array.isArray(h)) h.forEach(function (id) { m[id] = 1; });
    return m;
  }
  function hideVideo(id) {
    var h = (Settings.get('hidden') || []).filter(function (x) { return x !== id; });
    h.unshift(id);
    Settings.set('hidden', h.slice(0, 300));
  }
  function removeHist(id) {
    Settings.set('history', history().filter(function (x) { return x.id !== id; }));
    var pos = Settings.get('pos') || {};
    delete pos[id];
    Settings.set('pos', pos);
  }
  function dropCard(c) {
    c.classList.add('gone');
    setTimeout(function () {
      var g = c.parentNode;
      if (!g) return;
      g.removeChild(c);
      // prazna grupa u historiji: skini i njen naslov
      if (!g.children.length && g.previousSibling && g.previousSibling.className === 'shelf-title') g.parentNode.removeChild(g.previousSibling);
      syncLibrary();
    }, 220);
  }
  // poslije brisanja u biblioteci odmah osvježi brojač taba i prazno stanje (bez ponovnog renderovanja cijele stranice)
  function syncLibrary() {
    if (page !== 'history') return;
    var tabs = document.querySelector('.page .chips.tabs');
    if (tabs && tabs.children.length > 1) tabs.children[1].textContent = laterLabel(later().length);
    if (histTab === 'later') {
      var lg = document.querySelector('.page .grid.hl');
      if (lg && !lg.children.length) {
        var p = lg.parentNode;
        p.removeChild(lg);
        msg(p, 'Ovdje su videi koje sačuvaš za kasnije: ⋮ na kartici → „Gledaj kasnije”.');
      }
      return;
    }
    var list = $('histlist');
    if (!list || list.querySelector('.card') || list.querySelector('.msg')) return;
    msg(list, history().length ? 'Nema rezultata.' : 'Još ništa nisi gledao.');
  }
  // stranica na koju se vraća BACK sa kanala (pretraga/kanal se ne mogu vratiti bez upita)
  function here() { return page === 'history' || page === 'channels' ? page : 'home'; }

  function copyText(t) {
    var ok = function () { toast('Link kopiran'); };
    var old = function () {
      if (ANDROID && Android.copy) { Android.copy(t); ok(); return; }
      var a = el('textarea');
      a.value = t; a.style.position = 'fixed'; a.style.opacity = '0';
      document.body.appendChild(a);
      a.select();
      try { if (document.execCommand('copy')) ok(); else toast(t, 5000); } catch (e) { toast(t, 5000); }
      document.body.removeChild(a);
    };
    if (ANDROID && Android.copy) old();
    else if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(ok, old);
    else old();
  }
  function share(title, url) {
    if (ANDROID && Android.share) Android.share(title || '', url);
    else if (navigator.share) navigator.share({ title: title, url: url }).catch(function () {});
    else copyText(url);
  }

  var sheetEl = null, sheetBack = null, sheetFocus = null;
  function sheet(head, items, onUp) {
    closeSheet(true);
    sheetBack = Nav.current();
    sheetFocus = document.activeElement && document.activeElement !== document.body ? document.activeElement : null;
    var bg = el('div'), box = el('div', 'sh');
    bg.id = 'sheet';
    bg.setAttribute('role', 'dialog');
    bg.setAttribute('aria-modal', 'true');
    var ht = head && head.querySelector ? head.querySelector('.t') : null;
    bg.setAttribute('aria-label', ht && ht.textContent ? ht.textContent : 'Meni');
    box.tabIndex = -1;
    var gw = el('div', 'grabw');
    gw.appendChild(el('div', 'grab'));
    box.appendChild(gw);
    dragSheet(bg, box, gw, onUp);
    if (onUp) gw.title = 'Povuci gore za pokretanje';
    if (head) box.appendChild(head);
    items.forEach(function (it) {
      var b = el('div', 'f si');
      b.tabIndex = 0;
      b.setAttribute('role', 'button');
      b.innerHTML = iconSvg(it.icon);
      b.appendChild(el('span', '', it.label));
      b.onclick = function () { closeSheet(); it.fn(); };
      b.onkeydown = function (e) {
        if (e.keyCode === 13 || e.keyCode === 32) { e.preventDefault(); b.onclick(); }
      };
      box.appendChild(b);
    });
    // fokus ostaje unutar dijaloga dok je otvoren; ESC/BACK ga zatvara
    bg.addEventListener('keydown', function (e) {
      var k = e.keyCode;
      if (k === 27 || k === 10009) { e.preventDefault(); closeSheet(); return; }
      if (k !== 9) return;
      var f = Array.prototype.filter.call(box.querySelectorAll('[tabindex]'), function (x) { return x.tabIndex >= 0; });
      if (!f.length) { box.focus(); e.preventDefault(); return; }
      var i = f.indexOf(document.activeElement), n = (i + (e.shiftKey ? -1 : 1) + f.length) % f.length;
      f[n].focus();
      e.preventDefault();
    });
    bg.appendChild(box);
    document.body.appendChild(bg);
    sheetEl = bg;
    void bg.offsetWidth;
    bg.classList.add('on');
    setTimeout(function () { if (sheetEl === bg) try { box.focus(); } catch (e) {} }, 0);
  }
  /* povlačenje ručke prema dolje zatvara meni; tap na ručku također; kratko povlačenje se vraća */
  function dragSheet(bg, box, gw, onUp) {
    var y0 = 0, dy = 0, on = false;
    gw.addEventListener('touchstart', function (e) {
      if (e.touches.length !== 1) return;
      y0 = e.touches[0].clientY; dy = 0; on = true;
      box.style.transition = 'none';
    }, { passive: true });
    gw.addEventListener('touchmove', function (e) {
      if (!on) return;
      var raw = e.touches[0].clientY - y0;
      dy = onUp ? Math.max(-160, raw) : Math.max(0, raw); // gore samo kad meni zna šta s tim (otvori video)
      box.style.transform = 'translateY(' + (dy < 0 ? dy / 2 : dy) + 'px)';
      bg.style.backgroundColor = 'rgba(0,0,0,' + (0.55 * Math.max(0, 1 - dy / 300)) + ')';
      e.preventDefault();
    }, { passive: false });
    function end() {
      if (!on) return;
      on = false;
      box.style.transition = '';
      bg.style.backgroundColor = '';
      if (onUp && dy < -60) { // povuci ručku gore = otvori video (kao YouTube-ov "povuci za pun ekran")
        box.style.transform = '';
        closeSheet();
        onUp();
        return;
      }
      if (dy > 70 || dy > -4 && dy < 4) { box.style.transform = ''; closeSheet(); } // dy<4: obični tap na ručku
      else box.style.transform = '';
    }
    gw.addEventListener('touchend', end);
    gw.addEventListener('touchcancel', function () { dy = 0; end(); });
    gw.onclick = function () { closeSheet(); };
  }
  function closeSheet(now) {
    if (!sheetEl) return false;
    var s = sheetEl, f = sheetFocus;
    sheetEl = null;
    sheetFocus = null;
    s.classList.remove('on');
    setTimeout(function () { if (s.parentNode) s.parentNode.removeChild(s); }, now ? 0 : 220);
    if (f && document.body.contains(f)) { try { f.focus(); } catch (e) {} }
    if (sheetBack && document.body.contains(sheetBack)) Nav.focus(sheetBack, true);
    return true;
  }

  function cardMenu(v, c) {
    var head = el('div', 'shh'), im = el('img'), tx = el('div', 'tx');
    im.src = thumbOf(v); im.alt = '';
    head.appendChild(im);
    tx.appendChild(el('div', 't', v.title));
    tx.appendChild(el('div', 'm', v.author || ''));
    head.appendChild(tx);
    var url = 'https://youtu.be/' + v.id, inL = inLater(v.id);
    var inH = history().some(function (h) { return h.id === v.id; });
    var items = [{ icon: inL ? 'check' : 'later', label: inL ? 'Ukloni iz „Gledaj kasnije”' : 'Gledaj kasnije', fn: function () {
      toggleLater(v);
      if (inL && page === 'history' && histTab === 'later') dropCard(c);
    } }];
    if (v.channelId) items.push({ icon: 'user', label: 'Idi na kanal' + (v.author ? ' · ' + v.author : ''), fn: function () { showChannel(v.channelId, v.author, here()); } });
    items.push({ icon: 'share', label: 'Podijeli', fn: function () { share(v.title, url); } });
    items.push({ icon: 'link', label: 'Kopiraj link', fn: function () { copyText(url); } });
    if (inH) items.push({ icon: 'del', label: 'Ukloni iz historije', fn: function () {
      removeHist(v.id);
      if (page === 'history') dropCard(c);
      toast('Uklonjeno iz historije');
    } });
    if (page !== 'history') items.push({ icon: 'block', label: 'Ne zanima me', fn: function () { hideVideo(v.id); dropCard(c); toast('Ovaj video se više neće prikazivati'); } });
    sheet(head, items, c && c.onclick ? function () { c.onclick(); } : null);
  }

  function setProgress(c) {
    var th = c.firstChild, pb = th.querySelector('.pb'), pr = progressOf(c._vid);
    if (pr <= 0.02) { if (pb) th.removeChild(pb); return; }
    if (!pb) { pb = el('div', 'pb'); pb.appendChild(el('i')); th.appendChild(pb); }
    pb.firstChild.style.width = Math.min(100, pr * 100) + '%';
  }

  function skeleton() {
    var c = el('div', 'card sk');
    c.appendChild(el('div', 'th'));
    c.appendChild(el('div', 't'));
    c.appendChild(el('div', 'm'));
    return c;
  }

  function grid(list) {
    var g = el('div', 'grid');
    list.forEach(function (v) { g.appendChild(card(v)); });
    return g;
  }

  function chip(text, fn, cls) {
    var c = el('button', 'f chip' + (cls ? ' ' + cls : ''), text);
    c.onclick = fn;
    return c;
  }

  /* horizontalni red s naslovom; items = niz elemenata */
  function shelf(parent, title, sub) {
    var s = el('div', 'shelf');
    if (title) {
      var t = el('div', 'shelf-title', title);
      if (sub) t.appendChild(el('small', '', sub));
      s.appendChild(t);
    }
    var wrap = el('div', 'rowwrap'), row = el('div', 'row');
    wrap.appendChild(row);
    var l = el('div', 'rarr l', '‹'), r = el('div', 'rarr r', '›');
    l.onclick = function () { Nav.scrollRow(row, -1); };
    r.onclick = function () { Nav.scrollRow(row, 1); };
    wrap.appendChild(l);
    wrap.appendChild(r);
    s.appendChild(wrap);
    parent.appendChild(s);
    s.row = row;
    return s;
  }

  /* beskonačna lista: dodaje kartice iz stranice pg u box (red ili mreža); Nav zove box._more() blizu kraja.
     Telefon: stranica se dodaje u dijelovima (12 kartica), ostatak na _more() — bez čekanja mreže i bez
     300+ kartica/40.000 px u prvom prikazu (F8). Skrolanje i BACK vraćanje pozicije rade kao i prije. */
  function feedInto(box, pg, seen) {
    var my = view._gen, busy = false, empty = 0, hid = hiddenMap();
    var CHUNK = ANDROID ? 12 : 0, q = [], qmore = null;
    seen = seen || {};
    var flush = function (max) {
      var n = 0;
      while (q.length && (!max || n < max)) { box.appendChild(card(q.shift())); n++; }
      return n;
    };
    var add = function (p) {
      var arr = [];
      (p.items || []).forEach(function (v) { if (seen[v.id] || hid[v.id]) return; seen[v.id] = 1; arr.push(v); });
      qmore = p.more || null;
      if (CHUNK && arr.length > CHUNK) { q = q.concat(arr.slice(CHUNK)); arr = arr.slice(0, CHUNK); }
      var n = 0;
      arr.forEach(function (v) { box.appendChild(card(v)); n++; });
      box._more = qmore || q.length ? function () {
        if (busy) return;
        if (q.length) { flush(CHUNK); return; } // ostatak iste stranice: odmah, bez mreže
        if (!qmore) { box._more = null; return; }
        busy = true;
        var sk = skeleton(), next = qmore;
        box.appendChild(sk);
        next().then(function (np) {
          if (my !== view._gen) return;
          box.removeChild(sk);
          busy = false;
          add(np);
        }, function () { if (sk.parentNode) box.removeChild(sk); busy = false; });
      } : null;
      // cijela stranica duplikata -> odmah sljedeća (najviše 3 puta zaredom)
      empty = n ? 0 : empty + 1;
      if (!n && box._more && empty < 4) box._more();
      // do kraja nema nijedne kartice (npr. svi rezultati su shorts) -> javi prazno stanje
      else if (!n && box._onempty && !box.querySelector('.card.f') && document.body.contains(box)) box._onempty();
    };
    add(pg);
  }

  /* spoji više izvora u jedan feed (naizmjenično), bez live prijenosa */
  function merged(pages) {
    var out = [], max = Math.max.apply(null, pages.map(function (p) { return p.items.length; }).concat(0));
    for (var i = 0; i < max; i++) pages.forEach(function (p) { var v = p.items[i]; if (v && !v.live) out.push(v); });
    var live = pages.filter(function (p) { return p.more; });
    return {
      items: out,
      // po 3 izvora odjednom (TV), ostali dolaze na red sljedeći put
      more: live.length ? function () {
        var rest = live.slice(3).map(function (p) { return { items: [], more: p.more }; });
        return Promise.all(live.slice(0, 3).map(function (p) { return p.more().catch(function () { return { items: [] }; }); }))
          .then(function (np) { return merged(rest.concat(np)); });
      } : null
    };
  }

  function relatedFeed(ids) {
    return Promise.all(ids.map(function (id) { return YT.relatedPage(id).catch(function () { return { items: [] }; }); })).then(merged);
  }

  /* svi izvori paralelno; grešku prijavi samo ako nijedan nije uspio (F12: offline početna) */
  function allPages(list) {
    return Promise.all(list.map(function (p) {
      return p.then(function (pg) { return { pg: pg }; }, function (e) { return { e: e }; });
    })).then(function (rs) {
      var ok = rs.filter(function (r) { return r.pg; }).map(function (r) { return r.pg; });
      if (!ok.length) {
        for (var i = 0; i < rs.length; i++) if (rs[i].e) throw rs[i].e;
        throw new Error('Mrezna greska');
      }
      return merged(ok);
    });
  }

  function watchedSeen() {
    var s = {};
    history().forEach(function (h) { s[h.id] = 1; });
    return s;
  }

  /* red koji se puni asinhrono (skeleton kartice dok čeka); promise daje listu ili stranicu {items, more} */
  function asyncShelf(parent, title, promise, onList, sub, seen) {
    var s = shelf(parent, title, sub), my = view._gen;
    for (var i = 0; i < 5; i++) s.row.appendChild(skeleton());
    promise.then(function (res) {
      if (my !== view._gen) return;
      var pg = res && res.items ? res : { items: res || [] };
      if (!pg.items.length) { s.parentNode.removeChild(s); return; }
      s.row.innerHTML = '';
      feedInto(s.row, pg, seen);
      if (!s.row.children.length) { s.parentNode.removeChild(s); return; }
      if (onList) onList(pg.items);
    }, function () { if (s.parentNode) s.parentNode.removeChild(s); });
    return s;
  }

  /* mreža koja se puni asinhrono i učitava još pri skrolanju.
     retry (opciono) dodaje "Pokušaj ponovo" kad zahtjev padne; onEmpty zamjenjuje praznu mrežu porukom;
     onReady se zove odmah poslije prvog punjenja (fokus ne smije čekati 100 ms interval);
     onErr (opciono) preuzima prikaz greške umjesto podrazumijevanog errMsg (npr. početna ima svoj netBox). */
  function asyncGrid(parent, promise, seen, onEmpty, retry, onReady, onErr) {
    var g = el('div', 'grid'), my = view._gen;
    for (var i = 0; i < 10; i++) g.appendChild(skeleton());
    var remove = function () {
      if (g.parentNode) g.parentNode.removeChild(g);
    };
    g._onempty = function () { remove(); if (onEmpty) onEmpty(); };
    parent.appendChild(g);
    promise.then(function (pg) {
      if (my !== view._gen || !document.body.contains(g)) return; // stranica/pretraga se promijenila
      g.innerHTML = '';
      feedInto(g, pg, seen);
      if (onReady) onReady(g);
    }, function (e) {
      if (my !== view._gen || !document.body.contains(g)) return;
      var par = g.parentNode;
      remove();
      if (onErr) onErr(e);
      else if (par) errMsg(par, e, retry);
    });
    return g;
  }

  /* Historija stranica: BACK/swipe se vraća na prethodnu (s pozicijom skrola), swipe u suprotnu stranu ide naprijed.
     Tab (traka/donja navigacija) počinje novi niz; pretraga, kanal i žanr se slažu jedno na drugo. */
  var cur = null, backSt = [], fwdSt = [], restoring = false, refreshing = false;
  function rec(fn, args, top) {
    var n = { fn: fn, args: Array.prototype.slice.call(args), top: top, sy: 0 };
    if (!restoring && !refreshing && cur) {
      var same = cur.fn === fn && JSON.stringify(cur.args) === JSON.stringify(n.args);
      if (top) { backSt = []; fwdSt = []; }
      else if (!same) {
        cur.sy = view.scrollTop;
        backSt.push(cur);
        if (backSt.length > 30) backSt.shift();
        fwdSt = [];
      }
    }
    cur = n;
  }
  function step(dir) {
    var from = dir < 0 ? backSt : fwdSt, to = dir < 0 ? fwdSt : backSt;
    if (!from.length || !cur) return false;
    cur.sy = view.scrollTop;
    to.push(cur);
    var n = from.pop();
    restoring = true;
    try { n.fn.apply(null, n.args); } finally { restoring = false; }
    // sadržaj se često dolijeva asinhrono: vrati skrol čim stranica naraste
    var tries = 0, iv = setInterval(function () {
      view.scrollTop = n.sy;
      if (view.scrollTop >= n.sy - 2 || ++tries > 28) { clearInterval(iv); return; }
      // telefon: feed se dodaje u dijelovima (F8), pa za duboku poziciju zatraži još kartica
      var gs = view.querySelectorAll('.grid'), g = gs[gs.length - 1];
      if (g && g._more) g._more();
    }, 120);
    return true;
  }
  function canStep(dir) { return (dir < 0 ? backSt : fwdSt).length > 0; }
  function refresh() {
    if (!cur) return;
    refreshing = true;
    try { cur.fn.apply(null, cur.args); } finally { refreshing = false; }
  }

  function newPage(name) {
    page = name;
    view._gen = (view._gen || 0) + 1;
    view.innerHTML = '';
    Nav.resetScroll();
    Array.prototype.forEach.call(document.querySelectorAll('.navbtn'), function (b) {
      b.classList.toggle('sel', b.getAttribute('data-go') === (name === 'channel' ? 'channels' : name));
    });
    var p = el('div', 'page');
    view.appendChild(p);
    return p;
  }

  function msg(p, text) { var m = el('div', 'msg', text); p.appendChild(m); return m; }

  /* mrežna greška: kratka poruka bez internog URL-a + "Pokušaj ponovo" (F5/F16) */
  function isNetError(e) {
    if (typeof navigator !== 'undefined' && navigator.onLine === false) return true;
    return /Mrezna greska|Mrežna greška|Timeout|Failed to fetch|NetworkError|Network request failed/i.test((e && (e.message || e.name)) || '');
  }
  function errText(e) {
    if (isNetError(e)) return 'Nema internet veze. Provjeri vezu i pokušaj ponovo.';
    return 'Greška: ' + ((e && e.message) || e);
  }
  function errMsg(parent, e, retry) {
    var m = msg(parent, errText(e));
    if (retry) m.appendChild(chip('Pokušaj ponovo', retry));
    return m;
  }

  function focusFirstIn(p) {
    var f = Nav.cands().filter(function (e) { return p.contains(e); })[0];
    if (f) Nav.focus(f);
  }

  function history() { return Settings.get('history') || []; }

  function continueList() {
    return history().filter(function (v) { var p = progressOf(v.id); return p > 0.03 && p < 0.95; });
  }

  /* kanali iz historije, sortirani po broju gledanja */
  function topChannels() {
    var map = {}, out = [];
    history().forEach(function (v) {
      if (!v.channelId) return;
      if (!map[v.channelId]) { map[v.channelId] = { id: v.channelId, name: v.author, count: 0 }; out.push(map[v.channelId]); }
      map[v.channelId].count++;
    });
    return out.sort(function (a, b) { return b.count - a.count; });
  }

  /* ---------- Početna ---------- */
  function hero(p) {
    var h = el('div');
    h.id = 'hero';
    p.appendChild(h);
    h.set = function (v, label) {
      h.innerHTML = '';
      h._v = v;
      var fb = thumbOf(v), bg = el('img', 'bg');
      bg.onload = function () { if (bg.naturalWidth < 200 && /maxresdefault/.test(bg.src)) bg.src = fb.replace('mqdefault', 'hqdefault'); };
      bg.onerror = function () { if (bg.getAttribute('src') !== fb) bg.setAttribute('src', fb); }; // samo jedan fallback, da offline ne uđe u petlju
      bg.src = 'https://i.ytimg.com/vi/' + v.id + '/maxresdefault.jpg';
      h.appendChild(bg);
      h.appendChild(el('div', 'fade'));
      var inn = el('div', 'in');
      inn.appendChild(el('div', 'lbl', label));
      inn.appendChild(el('h1', '', v.title));
      inn.appendChild(el('div', 'meta', [v.author, v.length, metaLocal(v)].filter(Boolean).join('  ·  ')));
      var pr = progressOf(v.id);
      if (pr > 0.02) {
        var pb = el('div', 'hpb'), i = el('i');
        i.style.width = pr * 100 + '%';
        pb.appendChild(i);
        inn.appendChild(pb);
      }
      var btns = el('div', 'btns');
      var play = el('button', 'f btn pri');
      play.innerHTML = iconSvg('play');
      play.appendChild(document.createTextNode(pr > 0.02 ? 'Nastavi' : 'Gledaj'));
      play.onclick = function () { Player.open(v); };
      btns.appendChild(play);
      if (v.channelId) {
        var ch = el('button', 'f btn');
        ch.innerHTML = iconSvg('user');
        ch.appendChild(document.createTextNode(v.author || 'Kanal'));
        ch.onclick = function () { showChannel(v.channelId, v.author, 'home'); };
        btns.appendChild(ch);
      }
      inn.appendChild(btns);
      h.appendChild(inn);
    };
    return h;
  }

  function showHome() {
    rec(showHome, arguments, true);
    var p = newPage('home'), hid = hiddenMap();
    var hist = filterHidden(history(), hid), cont = filterHidden(continueList(), hid);
    var h = hero(p), heroSet = false;
    var setHero = function (v, label) {
      if (heroSet || !v) return;
      heroSet = true;
      h.set(v, label);
      var c = Nav.current();
      if (!c || !document.body.contains(c)) focusFirstIn(p);
    };
    if (cont.length) setHero(cont[0], 'Nastavi gledati');
    else if (hist.length) setHero(hist[0], 'Nedavno gledano');

    var topics = shelf(p, 'Teme');
    TOPICS.forEach(function (t) { topics.row.appendChild(chip(t, function () { showSearch(topicQuery(t), 'home'); })); });

    /* F12: bez mreže početna ne smije ostati samo na temama/kešu. Poruka stoji odmah ispod tema
       (vidljiva bez skrolanja), a mrežni dio se preskače dok se veza ne vrati. */
    var netBox = el('div');
    p.appendChild(netBox);
    var netOff = typeof navigator !== 'undefined' && navigator.onLine === false;
    var t = null;
    var netErr = function (e) {
      if (!document.body.contains(p)) return;
      if (t && t.parentNode) t.parentNode.removeChild(t);
      netBox.innerHTML = '';
      errMsg(netBox, e || new Error('Mrezna greska'), function () { refresh(); });
    };
    if (netOff) netErr();

    if (cont.length > 1) {
      var cs = shelf(p, 'Nastavi gledati');
      cont.slice(0, 20).forEach(function (v) { cs.row.appendChild(card(v)); });
    }

    var lat = filterHidden(later(), hid);
    if (ANDROID && lat.length) {
      var ls = shelf(p, 'Gledaj kasnije');
      lat.slice(0, 20).forEach(function (v) { ls.row.appendChild(card(v)); });
    }

    var seen = watchedSeen(), ids = hist.map(function (v) { return v.id; });
    if (!netOff && hist.length) {
      asyncShelf(p, 'Za tebe', relatedFeed(ids.slice(0, 3)), function (list) { setHero(list[0], 'Preporučeno za tebe'); },
        'na osnovu onoga što gledaš', seen);
    }

    if (!netOff) topChannels().slice(0, 3).forEach(function (c) {
      asyncShelf(p, c.name || 'Kanal', YT.channel(c.id).then(function (r) { return { items: r.videos, more: r.more }; }), null, 'novo na kanalu');
    });

    var recent = hist.slice(cont.length ? 0 : 1, 20).filter(function (v) { return cont.indexOf(v) < 0; });
    if (recent.length) {
      var rs = shelf(p, 'Nedavno gledano');
      recent.forEach(function (v) { rs.row.appendChild(card(v)); });
    }

    var shelves = Settings.get('shelves').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
    if (!netOff) {
      shelves.forEach(function (q) {
        asyncShelf(p, q, YT.searchPage(q), function (list) { setHero(list[0], 'Istaknuto · ' + q); });
      });

      // na dnu: beskonačna mreža (slični videi starije historije + teme), učitava još dok se skrola
      t = el('div', 'shelf-title', 'Istraži još');
      t.appendChild(el('small', '', 'skrolaj dolje za još videa'));
      p.appendChild(t);
      var more = ids.slice(3, 9).map(function (id) { return YT.relatedPage(id); })
        .concat((hist.length ? shelves.slice(0, 2) : shelves.concat(['Muzika', 'Dokumentarci'])).map(function (q) {
          return YT.searchPage(q, { sort: 'views', when: 'year' });
        }));
      var feed = more.length ? allPages(more) : Promise.resolve({ items: [], more: null });
      asyncGrid(p, feed, seen, function () { if (t.parentNode) t.parentNode.removeChild(t); }, null, null, netErr);
    }
    focusFirstIn(p);
  }

  /* ---------- Pretraga ---------- */
  var SEARCH_FILTERS = [
    { key: 'sort', opts: [['rel', 'Relevantno'], ['views', 'Najgledanije'], ['new', 'Najnovije']] },
    { key: 'when', opts: [['any', 'Bilo kad'], ['today', 'Danas'], ['week', 'Ova sedmica'], ['month', 'Ovaj mjesec'], ['year', 'Ova godina']] },
    { key: 'len', opts: [['any', 'Sve dužine'], ['short', 'Do 4 min'], ['mid', '4–20 min'], ['long', 'Preko 20 min']] }
  ];
  var searchOpt;

  /* za poređenje imena: mala slova, bez kvačica i razmaka */
  function norm(s) {
    return String(s || '').toLowerCase().replace(/đ/g, 'd').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
  }

  function rememberSearch(q) {
    var s = (Settings.get('searches') || []).filter(function (x) { return x.toLowerCase() !== q.toLowerCase(); });
    s.unshift(q);
    Settings.set('searches', s.slice(0, 12));
  }

  function showSearch(q, from) {
    rec(showSearch, arguments, !q);
    var p = newPage('search');
    backTo = from || null;
    var box = el('div', 'sbox');
    var mag = el('i');
    mag.innerHTML = iconSvg('search');
    mag.firstChild.setAttribute('class', 'mag');
    var inp = el('input', 'f search-in');
    inp.placeholder = 'Pretraži YouTube…';
    inp.value = q || '';
    var goBtn = el('button', 'f btn pri', 'Traži');
    box.appendChild(mag.firstChild);
    box.appendChild(inp);
    box.appendChild(goBtn);
    p.appendChild(box);

    var sugWrap = el('div');
    p.appendChild(sugWrap);
    var out = el('div');
    p.appendChild(out);

    var res = el('div'), query = '';
    searchOpt = { sort: 'rel', when: 'any', len: 'any' };
    // rezultati (mreža koja se puni u beskonačnost) za trenutni upit i filtere
    var results = function (focusFirst) {
      res.innerHTML = '';
      var my = view._gen, gen = res._gen = (res._gen || 0) + 1, text = query;
      var top = el('div');
      res.appendChild(top);
      var g = asyncGrid(res, YT.searchPage(text, searchOpt).then(function (pg) {
        if (pg.corrected && pg.corrected.toLowerCase() !== text.toLowerCase())
          top.appendChild(chip('Jeste li mislili: ' + pg.corrected, function () { run(pg.corrected); }, 'ic'));
        return pg;
      }), {}, function () { msg(res, 'Nema rezultata za ove filtere.'); }, function () { results(false); });
      var wait = setInterval(function () {
        if (my !== view._gen || gen !== res._gen) { clearInterval(wait); return; }
        var c = g.querySelector('.card.f');
        if (c) { clearInterval(wait); if (focusFirst) Nav.focus(c); }
        else if (!g.querySelector('.sk')) clearInterval(wait); // prazno/greška: nema šta fokusirati
      }, 100);
      if (!focusFirst) return;
      // kanali čije ime odgovara upitu (npr. "halid beslic" -> kanal)
      YT.searchChannels(text).then(function (list) {
        if (my !== view._gen || gen !== res._gen) return;
        var q = norm(text);
        list = list.filter(function (c) { var n = norm(c.name); return n && (n.indexOf(q) >= 0 || q.indexOf(n) >= 0); }).slice(0, 4);
        if (!list.length) return;
        var s = shelf(top, 'Kanali');
        list.forEach(function (c) { s.row.appendChild(chanTile(c, 'search:' + text)); });
      }, function () {});
    };

    var filters = el('div');
    var filterRow = function () {
      filters.innerHTML = '';
      var c = el('div', 'chips');
      SEARCH_FILTERS.forEach(function (grp, gi) {
        if (gi) c.appendChild(el('div', 'sep'));
        grp.opts.forEach(function (o) {
          var b = chip(o[1], function () {
            searchOpt[grp.key] = o[0];
            Array.prototype.forEach.call(c.querySelectorAll('[data-k="' + grp.key + '"]'), function (x) {
              x.classList.toggle('sel', x === b);
            });
            results(false);
          }, searchOpt[grp.key] === o[0] ? 'sel' : '');
          b.setAttribute('data-k', grp.key);
          c.appendChild(b);
        });
      });
      filters.appendChild(c);
    };

    var run = function (text) {
      text = (text || inp.value).trim();
      if (!text) return;
      inp.value = text;
      inp.blur();
      clearTimeout(sugT);
      sugGen++; // prijedlozi koji su već krenuli ne smiju se vratiti iznad rezultata
      rememberSearch(text);
      sugWrap.innerHTML = '';
      out.innerHTML = '';
      query = text;
      out.appendChild(el('div', 'shelf-title', 'Rezultati: ' + text));
      filterRow();
      out.appendChild(filters);
      out.appendChild(res);
      results(true);
    };

    var chipsBlock = function (label, items, fn, cls) {
      if (!items.length) return;
      sugWrap.appendChild(el('div', 'lbl2', label));
      var c = el('div', 'chips');
      items.forEach(function (t) { c.appendChild(chip(t, function () { fn(t); }, cls)); });
      sugWrap.appendChild(c);
    };

    var idle = function () {
      sugWrap.innerHTML = '';
      chipsBlock('Nedavne pretrage', Settings.get('searches') || [], run, 'ic');
      chipsBlock('Teme', TOPICS, function (t) { run(topicQuery(t)); });
    };

    var sugT, sugQ = '', sugGen = 0;
    var suggest = function () {
      var text = inp.value.trim();
      if (text === sugQ) return;
      sugQ = text;
      clearTimeout(sugT);
      if (!text) { idle(); return; }
      var my = ++sugGen;
      sugT = setTimeout(function () {
        YT.suggest(text).then(function (list) {
          if (my !== sugGen || inp.value.trim() !== text) return;
          sugWrap.innerHTML = '';
          chipsBlock('Prijedlozi', list.slice(0, 10), run);
        }, function () {});
      }, 250);
    };

    goBtn.onclick = function () { run(); };
    inp.addEventListener('input', suggest);
    inp.addEventListener('keydown', function (e) {
      if (e.keyCode === 65376 || (e.keyCode === 13 && inp.value.trim())) { e.stopPropagation(); e.preventDefault(); run(); }
      else if (e.keyCode === 13 || e.keyCode === 65385) { e.stopPropagation(); inp.blur(); }
    });
    inp._activate = function () { inp.focus(); };
    if (q) run(q);
    else { idle(); Nav.focus(inp); }
  }

  /* ---------- Historija ---------- */
  function showHistory() {
    rec(showHistory, arguments, true);
    if (ANDROID) { phoneHistory(); return; }
    var p = newPage('history'), hist = history();
    p.appendChild(el('div', 'ptitle', 'Historija gledanja'));
    if (!hist.length) { msg(p, 'Još ništa nisi gledao.'); return; }
    var bar = el('div', 'chips');
    bar.appendChild(chip('Obriši historiju', function () {
      Settings.set('history', []);
      Settings.set('pos', {});
      toast('Historija obrisana');
      showHistory();
    }));
    p.appendChild(bar);
    p.appendChild(grid(hist));
    focusFirstIn(p.querySelector('.grid'));
  }

  /* telefon: historija grupisana po danima, pretraga, pauza; drugi tab "Gledaj kasnije" */
  var histTab = 'hist';
  function dayLabel(at) {
    if (!at) return 'Starije';
    var d = new Date();
    d.setHours(0, 0, 0, 0);
    var t = d.getTime();
    return at >= t ? 'Danas' : at >= t - 864e5 ? 'Jučer' : at >= t - 6 * 864e5 ? 'Ova sedmica' : 'Starije';
  }

  // čip koji traži drugi dodir u 3 s (brisanje se ne može vratiti)
  function confirmChip(text, fn) {
    var armed = 0, c = chip(text, function () {
      if (Date.now() - armed < 3000) { fn(); return; }
      armed = Date.now();
