  var RESUME_KEY = 'tztPlayer';
  function savePlayerForReload() {
    try {
      var P = window.Player, st = P && P.session ? P.session() : null;
      if (st) sessionStorage.setItem(RESUME_KEY, JSON.stringify(st));
      else sessionStorage.removeItem(RESUME_KEY);
