  }
  function restorePlayerAfterReload() {
    var st = null;
    try {
      st = JSON.parse(sessionStorage.getItem(RESUME_KEY) || 'null');
      sessionStorage.removeItem(RESUME_KEY);
    } catch (e) {}
    var P = window.Player;
    if (!st || !st.v || !st.v.id || !P) return false;
    try {
      st.v.t = st.t || 0; // nastavi od iste pozicije
      P.open(st.v, true);
      if (st.mini) setTimeout(function () { try { P.mini(true); } catch (e) {} }, 0);
      return true;
    } catch (e) { dbg('resume ' + (e && e.message)); return false; }
  }

