      // telefon treba APK, TV web paket (ota.js)
      var re = ANDROID ? /\.apk$/i : /^TizenTube-web\.json$/i;
      var as = (j.assets || []).filter(function (x) { return re.test(x.name); })[0];
      if (!newer || !as) return null;
      // TV: github.com/.../download nema CORS zaglavlja, raw.githubusercontent.com ima (release.ps1 commita paket u repo)
      return { v: v, url: ANDROID ? as.browser_download_url : 'https://raw.githubusercontent.com/Hury999/tizentube-releases/master/TizenTube-web.json' };
    });
