    else if (st === 'install') updBtn.textContent = 'Instaliram…';
    else if (st === 'perm') { updBtn.textContent = 'Ažuriraj'; toast('Dozvoli instaliranje za TizenTube, pa ponovo pritisni Ažuriraj', 6000); }
    else if (st === 'err') { updBtn.textContent = 'Ažuriraj'; toast('Greška: ' + arg, 5000); }
  };
