      try { localStorage.removeItem('tt_ota'); localStorage.removeItem('tt_ota_try'); localStorage.setItem('tt_ota', t); }
      catch (e) { throw new Error('nema mjesta za paket'); }
      btn.textContent = 'Restartujem…';
      toast('Verzija ' + b.v + ' skinuta, restartujem…');
      setTimeout(function () { location.reload(); }, 1500);
    }).catch(function (e) {
      btn.textContent = 'Ažuriraj';
      toast('Greška: ' + (e && e.message || e), 5000);
    });
  }
  function updateClick(btn) {
    updBtn = btn;
    if (btn._url && !ANDROID) { tvUpdate(btn); return; }
    if (btn._url) { btn.textContent = 'Skidam…'; Android.update(btn._url); return; }
    btn.textContent = 'Provjeravam…';
    latestRelease().then(function (n) {
      if (!n) { btn.textContent = 'Provjeri ažuriranja'; toast('Imaš najnoviju verziju (' + APP_VER + ')'); return; }
      if (!ANDROID && !window.tizen) { btn.textContent = 'Provjeri ažuriranja'; toast('Nova verzija ' + n.v + ': github.com/Hury999/tizentube-releases', 8000); return; }
