  window.ttBack = function () {
    try { onKeyDown({ keyCode: 10009, preventDefault: function () {} }); }
    catch (e) { dbg('ttBack ' + (e && e.message)); }
  };
  document.addEventListener('DOMContentLoaded', init);
  return { step: step, canStep: canStep, refresh: refresh, onPlayerClosed: onPlayerClosed, showChannel: showChannel, avatarEl: avatarEl,
    qa: { repairSettings: repairSettings, filterHidden: filterHidden, hiddenMap: hiddenMap, laterLabel: laterLabel, topicQuery: topicQuery,
      metaLocal: metaLocal, parseViews: parseViews, ageText: ageText, errText: errText, isNetError: isNetError,
      savePlayerForReload: savePlayerForReload, restorePlayerAfterReload: restorePlayerAfterReload } };
})();

