/* Android telefon: izgled za telefon (css/phone.css, uspravno i položeno), nativni scroll s beskonačnim listama,
   dvostruki tap lijevo/desno u playeru = ±10 s, bez long-press "back".
   Pokreti kao YouTube: video povuci dolje = mini player, mini gore/tap = nazad, mini u stranu = zatvori,
   video gore (uspravno) = cijeli ekran. */
(function () {
  if (!ANDROID) return;
  var root = document.documentElement;
  root.classList.add('touch', 'phone');
