  if (vp) vp.setAttribute('content', 'width=device-width, initial-scale=1');

  // izrez kamere (notch): Java javlja sigurnu zonu (gore,lijevo,desno,dolje u px), CSS je koristi kao --sat/--sal/--sar/--sab
  window.ttSafe = function (v) {
    var a = String(v || '').split(',');
    ['--sat', '--sal', '--sar', '--sab'].forEach(function (k, i) { root.style.setProperty(k, (+a[i] || 0) + 'px'); });
  };
  try { if (Android.safe) ttSafe(Android.safe()); } catch (e) { /* stara verzija APK-a */ }

  // beskonačne liste: zadnja mreža stranice kad se skrola blizu dna, red kad se povuče blizu kraja
  document.addEventListener('scroll', function (e) {
    var t = e.target;
    if (t.id === 'view') {
      if (t.scrollTop + t.clientHeight < t.scrollHeight - t.clientHeight * 1.5) return;
      var grids = t.querySelectorAll('.grid'), g = grids[grids.length - 1];
      if (g && g._more) g._more();
    } else if (t.classList && t.classList.contains('rowwrap')) {
      var row = t.firstChild;
      if (row && row._more && t.scrollLeft + t.clientWidth > t.scrollWidth - t.clientWidth * 2) row._more();
    }
  }, true);

  // player: dvostruki tap na lijevu/desnu trećinu videa premota 10 s (kao YouTube)
  var lastTap = 0, lastX = 0, dragEnd = 0, tapT = 0, TAP = 350;
  document.addEventListener('click', function (e) {
    if (Date.now() - dragEnd < 400) { e.stopImmediatePropagation(); e.preventDefault(); return; } // kraj povlačenja nije tap
    if (!Player.isOpen() || e.target.id !== 'video' && e.target.id !== 'player') return;
    var r = $('video').getBoundingClientRect(), now = Date.now();
