    var d = $('seekfx');
    if (!d) { d = el('div'); d.id = 'seekfx'; $('player').appendChild(d); }
    d.className = '';
    d.textContent = txt || (side < 0 ? '« 10 s' : '10 s »');
    d.style.top = r.top - $('player').getBoundingClientRect().top - $('player').clientTop + 'px'; // relativno na player (ima okvir ispod notcha)
